// Automatisch aus lamawiki/pl.json erzeugt (PyGameZ Web).
window.PG_WIKI = window.PG_WIKI || {};
window.PG_WIKI["pl"] = {"pages":[{"id":"start","category":"general","title":"Pierwsze kroki","keywords":["start","pomoc","wprowadzenie","menu","pauza","pełny ekran","pasek boczny","wieloosobowy"],"sections":[{"h":"Rozpoczynanie gry","body":["Grę możesz uruchomić na trzy sposoby: z listy gier na lewym pasku bocznym, z siatki gier na ekranie startowym albo bezpośrednio z tej wiki przez ekran przygotowania.","Przed każdą grą pojawia się ekran przygotowania: tam wybierasz tryb (np. jeden gracz lub wielu graczy) oraz dostajesz się do opcji i tej wiki.","Jeśli gra ma wiele trybów albo okno jest małe, Opcje, Wiki i Powrót ustawiają się na ekranie przygotowania w jednym rzędzie - dzięki temu wszystko pozostaje widoczne."]},{"h":"Ważne klawisze","body":["- [Esc] wstrzymuje i wznawia trwającą grę - w menu cofa.","- [F11] włącza i wyłącza pełny ekran.","- Zielony przycisk Powrót do menu kończy grę i zapisuje najlepszy wynik - tak samo jak przejście do innej gry z paska bocznego."]},{"h":"Pasek boczny","body":["Po lewej widzisz wszystkie gry z ich ikoną i twoim najlepszym wynikiem (gwiazdka). Trwająca gra pozostaje podświetlona; w małych oknach listę przewijasz kółkiem myszy.","Karta stanu w lewym dolnym rogu pokazuje nazwę gry, stan (zielony = trwa, złoty = pauza, czerwony = koniec gry), wynik oraz bieżącą liczbę klatek na sekundę."]},{"h":"Tryb wieloosobowy","body":["Lokalny tryb dla 2 graczy ma 20 gier: Snake, Pong, Air Hockey, Tic-Tac-Toe, Tetris (Versus), Asteroids (pojedynek kooperacyjny), Memory, Cztery w rzędzie, Pojedynek czołgów, Reversi, Yahtzee, Warcaby, Szachy, Młynek, Simon, Bilard, Minigolf, Pinball, Bowling i Battleship - wybierany na ekranie przygotowania.","W trybie jednoosobowym oba przypisania klawiszy sterują tą samą postacią; w trybie wieloosobowym po jednym na gracza (domyślnie: G1 = WASD, G2 = strzałki lub IJKL - patrz opcje).","Tetris oferuje też pojedynek z SI; w Battleship we dwoje ekran przekazania zasłania floty. Wersja przeglądarkowa jest wyłącznie jednoosobowa."]}]},{"id":"options","category":"general","title":"Opcje i sterowanie","keywords":["opcje","ustawienia","sterowanie","klawisze","rozdzielczość","fps","dźwięk","język","design","wyglad","motyw","stałe klawisze"],"sections":[{"h":"Dźwięk i wibracje","body":["Dźwięk włączasz/wyłączasz i ustawiasz głośność na ekranie opcji. Wszystkie efekty są generowane na żywo - nie ma plików audio.","Wibracje wprawiają w drgania podłączony gamepad (bez niego nic nie robią)."]},{"h":"Przypisania klawiszy","body":["Dostępne są trzy zestawy: WASD + strzałki, WASD + IJKL oraz strzałki + WASD.","Każdy pojedynczy klawisz można zmienić: kliknij wiersz lub potwierdź klawiszem Enter, a następnie naciśnij żądany klawisz. [Esc] anuluje.","Przypisania są oddzielne dla gracza 1 i gracza 2 oraz zapisywane na stałe.","Każdy gracz może zmienić pięć akcji: góra, dół, lewo, prawo i akcja. Niektóre gry mają dodatkowo stałe klawisze - np. schowek [C] i obrót w lewo [Z] w Tetrisie albo cofnięcie [U] w 2048, szachach i Sudoku. Działają tylko wtedy, gdy dany klawisz nie jest przypisany do żadnej akcji; wymienia je podpowiedź w ustawieniach i strona wiki gry."]},{"h":"Grafika i wydajność","body":["Rozdzielczość ustawia wewnętrzny obszar gry (od 480x360 do 1280x960). Mniejsza = mniejsze obciążenie, większa = ostrzejszy obraz.","Rozdzielczość automatyczna dopasowuje obszar gry do rozmiaru okna.","Opcje FPS (od 15 do 120) ustawiają docelową liczbę klatek na sekundę - mniej FPS oszczędza energię."]},{"h":"Wygląd","body":["W zakładce Wygląd wybierasz jeden z dziesięciu projektów interfejsu: UI v4.2 (domyślny: Midnight Glass - głęboki północny gradient z powoli dryfującymi miękkimi światłami w indygo, turkusie i magencie, delikatne ziarno filmu i panele jak matowe szkło), UI v4.1 (subtelne gwiazdy, Saturn i czarna dziura), cztery warianty ze wzorem UI v4.1.1 do v4.1.4 (jak v4.1, ale z kafelkowym wzorem zygzak w tle - czarny/antracytowy, niebieski/ciemnoniebieski, indygo z v4 na czerni i grafit z v4 na czerni), UI v4 (spokojny, płaski grafit), UI v3 (klasyczny interfejs ze zorzą i poświatą), UI v2 (pierwsza przebudowa interfejsu: granatowy gradient, gwiazdy i świecące przyciski, bez animacji) i UI v1 (wygląd sprzed przebudowy: jednolite tło, płaskie przyciski, bez efektów).","Każda karta pokazuje mały podgląd. Wybór działa natychmiast na obszar gry i pasek boczny oraz jest zapisywany w settings.json."]},{"h":"Język","body":["Interfejs jest dostępny w 14 językach: niemieckim, angielskim, francuskim, hiszpańskim, portugalskim, polskim, tureckim, duńskim, norweskim, szwedzkim, fińskim, czeskim, słoweńskim i chorwackim. Przełączasz go na ekranie opcji lub przez Język na pasku bocznym - ta wiki również zmienia język."]}]},{"id":"saving","category":"general","title":"Zapis i najlepsze wyniki","keywords":["zapis","najlepszy wynik","rekord","punkty","postęp","pliki","kopia zapasowa","backup","żetony lamy","ugc"],"sections":[{"h":"Najlepsze wyniki","body":["Każda gra zapisuje swój najlepszy wynik automatycznie po zakończeniu rundy. Nowy rekord pokazuje złoty baner - plus deszcz konfetti.","Najlepsze wyniki widzisz wszędzie: jako gwiazdkę na liście na pasku bocznym, na pasku przewijanym na ekranie startowym oraz na karcie stanu.","Tryby bez rekordu - np. Sprint i Ultra w Tetrisie, trasa dnia w Crossy Road czy 2048 z cofaniem - nie pokazują banera; ich najlepsze czasy i wyniki dnia gra zapisuje sama."]},{"h":"Co gdzie jest zapisywane?","body":["- settings.json: dźwięk, głośność, przypisania klawiszy, rozdzielczość, FPS, wygląd i opcje gier (np. tryb Snake, DAS/ARR w Tetrisie, wariant Sudoku, zasady Battleship).","- mem.json: najlepsze wyniki, wybrany język, osiągnięcia i statystyki - a do tego postępy wielu gier we własnych sekcjach (patrz niżej).","- mem-ngb.json: wizualne mody Snake (kolor głowy, siatka, baner).","- replay.json: zapisane powtórki z minigolfa i bowlingu.","- ugc.json: twoje własne dołki do minigolfa i poziomy Geometry Dash (udostępniane jako .lamapgzmap lub .lamapgzlevel).","Te pliki leżą bezpośrednio w folderze gry i wystarczy je skasować, aby wszystko zresetować."]},{"h":"Postępy w mem.json","body":["Każda gra z postępami ma w mem.json własną sekcję, na przykład:","- sudoku: rozwiązane poziomy z gwiazdkami i najlepszym czasem, rozpoczęte łamigłówki oraz Sudoku dnia z serią.","- casino: konto Banku Lamy - żetony Lamy dla Blackjacka, Pokera i Casino wraz z bilansem każdej gry.","- crossy: zebrane monety, kupione postacie i najlepszy wynik dnia w Crossy Road.","- tetris: najlepszy czas w Sprincie, najlepszy wynik w Ultra i bilans pojedynków z SI.","- g2048: zapisane partie 2048 i najlepsze wyniki dla każdego rozmiaru planszy i trybu.","- chess: twoje postępy w trybie zadań szachowych.","- geodash: najlepszy wynik procentowy każdego poziomu (Normalny i Trening), znalezione monety, próby i skoki w Geometry Dash.","- wordle: statystyki dla trybu, języka i długości słowa, stan słowa dnia oraz najlepsze wyniki.","Do tego m.in. minigolf, pinball, bowling i lamatowerdef z najlepszymi wynikami."]},{"h":"Automatyczna kopia zapasowa","body":["mem.json i settings.json są zapisywane bezpiecznie: najpierw do pliku tymczasowego, potem podmieniane w jednym kroku. Poprzednia wersja zostaje jako mem.json.bak lub settings.json.bak.","Jeśli mem.json kiedyś się uszkodzi, gra automatycznie wczyta kopię - rekordy, osiągnięcia i żetony Lamy nie przepadną."]},{"h":"Wskazówka","body":["Punkty są zapisywane po zakończeniu partii, przy wyjściu przez Powrót do menu, przy wyborze innej gry na pasku bocznym w trakcie rozgrywki oraz przy zamykaniu kolekcji. Tylko awaria lub siłowe zamknięcie programu sprawia, że trwająca partia przepada."]}]},{"id":"replays","category":"general","title":"Powtórki","keywords":["powtorka","nagranie","udostepnij","plik","archiwum","snake","tetris","bilard"],"sections":[{"h":"Czym jest powtórka?","body":["Sześć gier nagrywa swoje rundy: minigolf, bowling, bilard, pinball, Snake i Tetris. Zapisywany jest rzeczywisty ruch - klatka po klatce, trzydzieści razy na sekundę. Dlatego powtórka wygląda dokładnie tak jak twoja runda, razem z HUD-em i kartą wyników.","Minigolf, bowling, bilard i pinball mają krótkie sekwencje (uderzenie, rzut, zagranie, kula). Snake i Tetris idą bez przerwy - tam sekwencja to dziesięciosekundowy odcinek; Snake pokazywany jest zawsze z góry, nawet jeśli grałeś w 3D.","Nagrywana jest tylko bieżąca runda. Gdy zaczniesz od nowa, nagranie też rusza od początku."]},{"h":"Zapisywanie","body":["Jeśli runda była udana, naciśnij na końcu [P] - powtórka od razu ruszy. Klawisz [S] zapisuje ją w archiwum, [E] udostępnia jako plik, [Esc] wraca do ekranu końcowego.","Bilardowy tryb ćwiczeń nigdy się nie kończy: tam [P] pokazuje dotychczasowy przebieg między dwoma uderzeniami, a potem partia toczy się dalej.","Niezapisane nagrania znikają wraz z kolejną rundą; w archiwum mieści się 20 powtórek na grę."]},{"h":"Archiwum i odtwarzanie","body":["Przycisk Powtórki na pasku bocznym otwiera archiwum: jedna zakładka na grę, a w niej wynik, data i czas trwania każdego nagrania.","- [Enter] odtwarza, [Del] usuwa (naciśnij dwa razy), [Tab] zmienia grę.","- Podczas odtwarzania [Spacja] pauzuje, Lewo/Prawo przeskakuje do kolejnej sekwencji, Góra/Dół zmienia tempo (0,5x do 4x).","Kliknięcie na pasku postępu przenosi w dowolne miejsce."]},{"h":"Udostępnianie jako plik","body":["[E] zapisuje nagranie jako plik .lamapgzreplay - zarówno z archiwum, jak i zaraz po rundzie. Zawiera dokładnie jedną powtórkę i można go przekazać dalej jak tor minigolfa albo poziom Geometry Dash.","[I] wczytuje taki plik z powrotem. Trafia on do zakładki właściwej gry i ma tam małą strzałkę - znak, że pochodzi skądinąd.","Nagranie, które już jest w archiwum, nie zostanie wczytane po raz drugi."]},{"h":"Wyłączanie","body":["Przy pierwszym uruchomieniu i w opcjach w sekcji Nagrywanie można wyłączyć Nagrywaj powtórki - wtedy nic nie jest zapisywane.","Bardzo długie partie są skracane po dobrej półgodzinie; pasek pokazuje wtedy Nagranie skrócone.","Nagrania leżą w pliku replay.json w folderze gry, posortowane według gier. Możesz go skasować w dowolnej chwili."]}]},{"id":"achievements","category":"general","title":"Osiągnięcia i statystyki","keywords":["osiągnięcia","statystyki","postęp","rekord","zwycięstwa","czas gry","próg"],"sections":[{"h":"Przegląd","body":["Kolekcja śledzi twoje postępy: 107 osiągnięć i szczegółowe statystyki wszystkich 46 gier. Znajdziesz je pod przyciskiem Osiągnięcia i statystyki na pasku bocznym; zakładki przełączasz [Tab] lub kliknięciem."]},{"h":"Osiągnięcia","body":["Są trzy kategorie:","- Ogólne (23): cele dla całej kolekcji, np. rozpoczęte rozgrywki, wypróbowane gry, łączny czas gry, pobite rekordy i zwycięstwa - plus smaczki jak Nocny marek (granie po północy).","- Progi punktowe (37): jeden uczciwy cel punktowy na grę, dopasowany do jej skali.","- Wyjątkowe momenty (47): mat na SI, KNIFFEL, kafelki 2048 i 4096, T-Spin Double i Perfect Clear w Tetrisie, 25 rozwiązanych zadań szachowych, pierwsze Killer Sudoku, trafienie pojedynczej liczby w ruletce, lamowy jackpot na automacie, wygrana w Battleship bez utraty statku i więcej.","Przy odblokowaniu w prawym górnym rogu pojawia się złote powiadomienie z krótką fanfarą - nawet w trakcie gry.","Stare dane się liczą: przy pierwszym uruchomieniu po aktualizacji dotychczasowe rekordy zostają zaliczone automatycznie (bez fajerwerków powiadomień).","Zablokowane osiągnięcia pokazują pasek postępu, odblokowane - datę.","W 2048 i szachach partie z cofaniem ruchu lub podpowiedziami nie liczą się do rekordów ani osiągnięć - próbować wolno, oceniana jest tylko gra bez pomocy."]},{"h":"Statystyki","body":["U góry karty podsumowują wszystko: łączny czas gry, rozgrywki, zwycięstwa, pobite rekordy, wypróbowane gry i licznik osiągnięć - plus ulubiona gra (najwięcej czasu).","Poniżej tabela wymienia każdą zagraną grę z liczbą rozgrywek, czasem, zwycięstwami i rekordem, posortowaną według czasu gry. Kliknięcie wiersza otwiera daną grę.","Liczy się tylko aktywny czas gry - pauzy i menu nie. Zwycięstwa rejestrują gry z jasnym wynikiem (planszowe, karciane i logiczne) w trybie jednoosobowym."]},{"h":"Zapis","body":["Wszystko jest zapisywane lokalnie w mem.json (sekcje stats i achievements), razem z językiem i rekordami. Usunięcie pliku resetuje też osiągnięcia i statystyki."]}]},{"id":"snake-special","category":"general","title":"Snake specjalny","keywords":["rywalizacja","prestiż","hardcore","mody","personalizacja","automat","hazard","3d"],"sections":[{"h":"Tryb rywalizacji","body":["Tryb bez końca ze wspinaczką po poziomach: zaczynasz z dokładnie jednym jabłkiem. Im więcej jabłek zbierzesz w sumie, tym wyższy twój poziom - naraz pojawia się więcej jabłek, a mnożnik punktów rośnie (15 poziomów, do x16).","- Niebieskie jabłka otwierają automat do gry: stawką jest twoja długość, trzy jednakowe symbole = jackpot z jabłkami bonusowymi.","- Fioletowe jabłka (hazard) obstawiają część twojego rozmiaru: zwykle stawka 50 procent z mnożnikiem od x0.5 do x1.5.","Twój dokładny rozmiar jest pokazany jako liczba dziesiętna w lewym górnym rogu - każdy zakład opiera się na nim. Progi poziomów znajdują się w games/levels/snake-comp.json i można je dowolnie edytować."]},{"h":"Hardcore","body":["Przełączasz klawiszem [H] w ustawieniach rywalizacji: każde przyspieszenie pochłania długość, a fioletowe jabłka stają się bardziej ryzykowne (stawka od 75 do 90 procent, mnożnik od x0.25 do x2.25). Czerwona ramka oznacza ten tryb."]},{"h":"Prestiż","body":["Dostępny klawiszem [P] w trybie jednoosobowym: zebrane jabłka można zamienić na poziomy prestiżu, które dają trwałe premie. Postęp zachowuje się między rozgrywkami."]},{"h":"Mody / personalizacja","body":["W ustawieniach przez przycisk pędzla lub [C] : czysto wizualne menu, które nigdy nie zmienia rozgrywki.","- Głowa: kolor głowy węża (gotowe zestawy lub własny kolor RGB).","- Siatka: siatka współrzędnych z numerami wierszy i literami kolumn jako pomoc na dużych planszach.","- Baner: włącz/wyłącz baner mnożnika, a także rozmiar i przezroczystość - z podglądem na żywo.","Wszystko jest zapisywane w mem-ngb.json."]},{"h":"Widok 3D","body":["Klawiszem [V] w ustawieniach: plansza jest renderowana jako scena 3D, kamera podążająca unosi się za wężem, a sterowanie odbywa się względem kierunku patrzenia (dwa szybkie naciśnięcia = zawrócenie).","Klawiszem [K] otwierasz opcje kamery 3D: płynne potrząsanie, pole widzenia (FOV), wysokość kamery oraz przełącznik potrząsania przy skręcie. Grywalne w 3D: Klasyczny i Przeszkody (tylko jeden gracz)."]}]},{"id":"snake","category":"games","game":"SnakeGame","title":"Snake","keywords":["wąż","jabłko","przyspieszenie","rywalizacja","3d","portale"],"sections":[{"h":"Sterowanie","body":["Steruj klawiszami [W] [A] [S] [D] lub strzałkami. W 3D sterujesz względem kierunku patrzenia: lewo/prawo skręcają, dwa szybkie naciśnięcia = zawrócenie.","- Przyspieszenie: przytrzymaj [Space] lub Shift = podwójna prędkość. Pasek energii opróżnia się, a potem ładuje ponownie.","- Gracz 2 przyspiesza klawiszem Enter lub prawym Shiftem."]},{"h":"Tryby","body":["- Klasyczny: czysty snake.","- Speed rush: każde pożywienie przyspiesza cię.","- Przeszkody: śmiertelne bloki na planszy.","- Portale: pary teleportów przenoszą cię na drugą stronę planszy.","- Na czas: 60 sekund, jak najwięcej jabłek.","- Rywalizacja: tryb bez końca z poziomami, automatem do gry i jabłkami hazardowymi - szczegóły na stronie Snake specjalny.","Można też wybrać: przenikanie przez ściany, jabłka bonusowe, hardcore, widok 2D/3D klawiszem [V] oraz tryb wieloosobowy."]},{"h":"Punktacja","body":["Jabłka dają punkty (jabłka bonusowe losowo podwajają). Złote jabłka pojawiają się tymczasowo, dają dużo punktów i natychmiast uzupełniają przyspieszenie. W rywalizacji twój poziom mnoży wszystkie punkty."]},{"h":"Wskazówki","body":["- Używaj przyspieszenia na długich prostych, nie w ciasnych zakrętach.","- Przy włączonym przenikaniu możesz uciec przez krawędź, gdy sam się zablokujesz.","- W rywalizacji fioletowe jabłka opłacają się najbardziej, gdy masz zapas długości do obstawienia."]}]},{"id":"pong","category":"games","game":"PongGame","title":"Pong","keywords":["paletka","piłka","ai","klasyczny"],"sections":[{"h":"Sterowanie","body":["Gracz 1 porusza lewą paletką klawiszami [W] i [S] - w trybie wieloosobowym gracz 2 steruje prawą strzałkami.","Tryb ruchu można przełączać dla każdego sterowania: ciągły (naciśnij raz, paletka jedzie dalej) lub przytrzymanie (rusza się tylko, gdy trzymasz). Przełączasz klawiszem [X] dla sterowania 1 i [N] dla sterowania 2."]},{"h":"Zasady i punktacja","body":["Gra się do 5 punktów, przeciwko AI lub we dwóch.","Fizyka piłki przyspiesza z każdym odbiciem; kąt odbicia zależy od tego, w którym miejscu piłka trafia w paletkę."]},{"h":"Wskazówki","body":["- Uderzaj piłkę krawędzią paletki, aby tworzyć ostre kąty.","- Tryb przytrzymania daje precyzyjniejszą kontrolę, tryb ciągły szybsze reakcje."]}]},{"id":"airhockey","category":"games","game":"AirHockeyGame","title":"Air Hockey","keywords":["krążek","bijak","fizyka","bramki","power-upy","mysz"],"sections":[{"h":"Sterowanie","body":["W trybie jednoosobowym twój bijak podąża za myszą - dowolny klawisz przełącza z powrotem na sterowanie klawiaturą (8 kierunków).","W trybie wieloosobowym G1 gra po lewej klawiszami [W] [A] [S] [D], a G2 po prawej klawiszami [I] [J] [K] [L] ."]},{"h":"Ustawienia","body":["- Poziom AI: łatwy, średni lub trudny.","- [T] wybiera liczbę bramek do wygranej (3/5/7/10).","- [P] włącza/wyłącza power-upy: XL (większy bijak), BRAMKA (bramka przeciwnika się kurczy), prędkość (szybszy bijak). Power-upy należą do gracza, który ostatni dotknął krążka."]},{"h":"Wskazówki","body":["- Krążek przejmuje prędkość twojego bijaka - nabieraj rozpędu zamiast tylko blokować.","- Zostawaj za krążkiem: popychanie go w stronę własnej bramki grozi samobójem."]}]},{"id":"tictactoe","category":"games","game":"TicTacToeGame","title":"Tic-Tac-Toe","keywords":["krzyżyk","kółko","plansza","ai","mnk"],"sections":[{"h":"Sterowanie","body":["Stawiasz znaki kliknięciem myszy. Po zakończeniu gry: Enter lub kliknięcie = nowa runda, [S] = powrót do ustawień."]},{"h":"Tryby i ustawienia","body":["Rozmiary planszy od 3x3 do 9x9. Długość wygrywająca dostosowuje się: 3 w rzędzie na 3x3, 4 na 4x4, w przeciwnym razie 5.","Jeden gracz przeciwko AI (łatwy/średni/trudny) lub dwóch graczy lokalnie, X kontra O na zmianę."]},{"h":"Wskazówki","body":["- Trudne AI na 3x3 jest nie do pokonania - remis to najlepsze, co możesz tam osiągnąć.","- Na dużych planszach najważniejszy jest środek: przechodzi przez niego większość linii po 5."]}]},{"id":"breakout","category":"games","game":"BreakoutGame","title":"Breakout","keywords":["cegły","piłka","paletka","power-upy","combo","poziomy"],"sections":[{"h":"Sterowanie","body":["Poruszaj paletką myszą lub strzałkami. [Space] wypuszcza piłkę i strzela laserem. [P] lub [Esc] wstrzymuje."]},{"h":"Ustawienia","body":["- [1] [2] [3] wybiera poziom trudności.","- Lewo/prawo zmienia kolor piłki, góra/dół poziom startowy, [M] układ (standardowy lub pełny)."]},{"h":"Cegły i power-upy","body":["Rodzaje cegieł: normalna, stalowa (niezniszczalna), bomba (wybucha) i złota (dodatkowe punkty).","Power-upy: x2/x3 piłki, [L] laser, [F] kula ognia, [G] lepkość, [U] tarcza, monety za punkty bonusowe - plus mnożnik combo za szybkie trafienia."]},{"h":"Wskazówki","body":["- Prowadź piłkę wzdłuż bocznych ścian za blok cegieł - tam sama je zbija.","- Tarcza łapie dokładnie jedno przebicie: zachowaj ją na ryzykowne fazy z wieloma piłkami."]}]},{"id":"tetris","category":"games","game":"TetrisGame","title":"Tetris","keywords":["klocki","linie","obracanie","schowek","t-spin","sprint","ultra","maraton","versus","śmieci"],"sections":[{"h":"Tryby","body":["Solo: wariant wybierasz w ustawieniach. Maraton trwa bez końca, a poziom rośnie co 10 linii (poziom startowy 1-15) - do rekordu liczy się tylko Maraton.","- Sprint 40: skasuj 40 linii jak najszybciej; najlepszy czas zostaje zapisany.","- Ultra 2:00: zdobądź jak najwięcej punktów w dwie minuty; rekord zostaje zapisany.","Pojedynek z AI: grasz przeciw AI o trzech poziomach (Łatwy, Średni, Trudny). Kto kasuje linie, wysyła śmieci na drugą stronę; kogo stos pierwszy dotknie sufitu, ten jest K.O. Bilans z każdym poziomem zostaje zapisany.","2 graczy (tylko wersja PC): to samo we dwoje na jednej klawiaturze. Oba pola dostają zawsze tę samą kolejkę klocków."]},{"h":"Sterowanie","body":["[Lewo] [Prawo] przesuwają klocek - przytrzymany rusza po czasie DAS i dalej sunie w tempie ARR. [Góra] obraca w prawo, [Dół] to miękki zrzut, a klawisz akcji (domyślnie: [Spacja] ) zrzuca klocek od razu (twardy zrzut).","- [C] lub [Shift] odkłada klocek do schowka (raz na klocek), [Z] lub [Y] obraca w lewo, [X] w prawo.","- 2 graczy: gracz 1 odkłada klawiszem [Q] i obraca w lewo klawiszem [E], gracz 2 odkłada prawym [Shift] i obraca w lewo prawym [Ctrl].","- Te stałe klawisze działają tylko wtedy, gdy nie przypisałeś ich samodzielnie do żadnej akcji.","W Sprincie i Ultra [R] od razu zaczyna od nowa. Po grze: [R] = jeszcze raz, [S] = ustawienia - klawisze twardego zrzutu celowo niczego nie restartują.","W ustawieniach regulujesz DAS (opóźnienie do ciągłego ruchu), ARR (tempo potem, 0 ms = od razu do ściany) i cień klocka."]},{"h":"Nowoczesne zasady","body":["Klocki przychodzą w workach po 7: każdy z siedmiu klocków pojawia się dokładnie raz w każdej siódemce. Podgląd pokazuje 5 następnych.","Obrót działa według SRS: gdy klocek się zablokuje, gra próbuje do czterech pozycji zastępczych (wall kicks) - klocki da się więc obracać nawet wokół krawędzi.","Na dole klocek czeka 0,5 sekundy, zanim się zablokuje. Każdy ruch lub obrót zeruje ten czas, najwyżej 15 razy na daną głębokość.","Koniec gry: nowy klocek nie ma miejsca, klocek zablokuje się w całości nad polem albo śmieci wypchną stos górą."]},{"h":"Punktacja","body":["Wszystkie wartości razy poziom: Single 100 · Double 300 · Triple 500 · Tetris 800.","T-Spin: bez linii 400 · Single 800 · Double 1200 · Triple 1600. T-Spin Mini: 100 · 200 · 400.","- Back-to-Back: Tetris lub T-Spin zaraz po poprzednim liczy się x1,5.","- Kombo: każde kolejne skasowanie z rzędu daje dodatkowo 50 x kombo x poziom.","- Perfect Clear (całkiem puste pole): +800 / 1200 / 1800 / 2000, jako Tetris Back-to-Back +3200.","- Miękki zrzut daje 1 punkt, twardy 2 punkty za rząd."]},{"h":"T-Spiny","body":["T-Spin liczy się, gdy klocek T zablokuje się po obrocie, a co najmniej trzy z czterech narożników wokół jego środka są zajęte (ściany i dno też się liczą).","Jeśli oba narożniki po stronie, w którą wskazuje jego nosek, są zajęte, to pełny T-Spin, w przeciwnym razie Mini. Jeśli T wkręci się w lukę dużym kickiem (kolumna w bok, dwa rzędy w dół), zawsze liczy się jako pełny - tak powstaje T-Spin Triple.","Komunikaty nad polem pokazują T-SPIN, TETRIS, BACK-TO-BACK, KOMBO i PERFECT CLEAR."]},{"h":"Pojedynek i śmieci","body":["Atak: Double 1 · Triple 2 · Tetris 4 · T-Spin Single 2 · T-Spin Double 4 · T-Spin Triple 6 · Mini Double 1. Do tego +1 za Back-to-Back, od +1 do +5 za długie kombo i +10 za Perfect Clear.","Nadchodzące śmieci widać na pasku ostrzeżenia po lewej stronie pola: żółte jeszcze czekają, czerwone wyrosną przy twoim następnym klocku, który nie skasuje linii - najwyżej 8 rzędów na klocek, każda porcja ze wspólną dziurą.","Gdy sam kasujesz linie, twój atak najpierw znosi czekające śmieci; tylko reszta trafia do przeciwnika.","Co 40 sekund klocki spadają szybciej (do poziomu 12)."]},{"h":"Wskazówki i osiągnięcia","body":["- Buduj płasko i zostaw wolną kolumnę przy brzegu na klocek I - cztery linie naraz dają punkty i atak.","- Używaj schowka, by zachować I na Tetris albo odłożyć niepasujący klocek.","- W pojedynku opłaca się Back-to-Back: dwa Tetrisy z rzędu wysyłają 4 + 5 linii.","- Osiągnięcia: Tetris! (4 linie naraz), Mistrz obrotu (T-Spin Double), Czyściutko (Perfect Clear), Sprinter (Sprint 40 poniżej 2:00). We dwoje nie ma osiągnięć."]}]},{"id":"invaders","category":"games","game":"InvadersGame","title":"Invaders","keywords":["kosmici","fale","boss","bronie","arena","strzelanie"],"sections":[{"h":"Tryby","body":["- Klasyczny: klasyczny blok kosmitów schodzi w dół. W ustawieniach wybierasz ruch (tylko lewo/prawo lub swobodny z WASD) i celowanie (zawsze w górę lub w stronę myszy).","- Arena: swobodny ruch we wszystkich kierunkach, wrogowie napływają ze wszystkich krawędzi, celujesz w kierunku ruchu."]},{"h":"Bronie i power-upy","body":["Cztery bronie, przełączasz klawiszami [1] do [4] : blaster, strzał rozproszony, szybki ogień i laser.","Zniszczeni kosmici zostawiają power-upy: dodatkowe życie, tarczę i ulepszenia broni. Co 4. poziom ma bossa."]},{"h":"Wskazówki","body":["- Strzał rozproszony czyści gęste bloki, laser przebija całe kolumny - przełączaj zależnie od fali.","- Nigdy nie stój w miejscu na arenie: krąż wzdłuż krawędzi i ustawiaj wrogów w linii."]}]},{"id":"asteroids","category":"games","game":"AsteroidsGame","title":"Asteroids","keywords":["statek","skały","ufo","nadprzestrzeń","fale","wektor"],"sections":[{"h":"Sterowanie","body":["Góra daje ciąg w kierunku patrzenia, lewo/prawo obraca statek, klawisz akcji strzela. Statek dryfuje dalej (bezwładność) i przenika przez krawędzie ekranu.","Dół uruchamia nadprzestrzeń: awaryjny skok na losową pozycję z 4-sekundowym czasem odnowienia - i 12-procentowym ryzykiem rozpadu."]},{"h":"Punktacja i dodatki","body":["Skały rozpadają się na dwie mniejsze; trzy rozmiary dają 20/50/100 punktów. UFO (można wyłączyć) daje 200 punktów, dodatkowe życie pojawia się co 5000 punktów.","Power-upy ze zniszczonych skał: tarcza (6 sekund nietykalności), potrójny strzał i szybki ogień.","Pojedynek kooperacyjny (tryb wieloosobowy): oba statki lecą naraz z osobnymi życiami - wygrywa ten, kto ma więcej punktów."]},{"h":"Wskazówki","body":["- Najpierw zbij małe, szybkie odłamki, zanim rozbijesz kolejną dużą skałę.","- Nadprzestrzeń to ostateczność, nie sposób podróżowania - ryzyko jest realne."]}]},{"id":"pacman","category":"games","game":"PacmanGame","title":"Pac-Man","keywords":["duchy","kropki","labirynt","owoce","moc"],"sections":[{"h":"Sterowanie","body":["Poruszaj się strzałkami lub [W] [A] [S] [D] . Po zakończeniu gry: Enter = nowa, [S] = ustawienia.","Tunele po lewej i prawej przenoszą cię na drugą stronę."]},{"h":"Duchy i kropki mocy","body":["Cztery duchy polują ze swoimi oryginalnymi zachowaniami: Blinky ściga bezpośrednio, Pinky zastawia zasadzki, Inky używa wektora przez Blinky'ego, Clyde wycofuje się z bliska.","Kropki mocy sprawiają, że duchy stają się niebieskie i jadalne przez chwilę - łańcuch daje 200/400/800/1600 punktów. Owoce pojawiają się jako bonus, dodatkowe życie pojawia się przy 10 000 punktów."]},{"h":"Ustawienia i wskazówki","body":["Trudność normalna/trudna/ekstremalna ustawia prędkość duchów i czas przestrachu; każdy poziom jest szybszy.","- Zjadaj kropkę mocy tylko, gdy w pobliżu jest kilka duchów - liczy się łańcuch.","- Pamiętaj o fazach rozproszenia: przy każdej zmianie wszystkie duchy się odwracają."]}]},{"id":"flappy","category":"games","game":"FlappyGame","title":"Flappy Bird","keywords":["ptak","rury","monety","tarcza","medale","machanie"],"sections":[{"h":"Sterowanie","body":["[Space], strzałka w górę, [W] lub kliknięcie myszy sprawiają, że ptak macha skrzydłami - przechyla się zależnie od prędkości wznoszenia i opadania."]},{"h":"Punktacja i dodatki","body":["Każda minięta rura daje jeden punkt. W przerwach pojawiają się monety (bonus) oraz power-up tarczy, który wybacza dokładnie jedną kolizję.","Motywy dnia i nocy zmieniają się wraz z wynikiem; po zakończeniu gry są medale od brązowego do platynowego."]},{"h":"Wskazówki","body":["- Krótkie, regularne dotknięcia utrzymują tor lotu spokojniejszym niż rzadkie długie.","- Trudność ustala rozmiar przerwy i prędkość - przerwa zwęża się wraz ze wzrostem wyniku."]}]},{"id":"doodle","category":"games","game":"DoodleGame","title":"Doodle Jump","keywords":["skok","platformy","potwory","sprężyna","śmigło","wysokość"],"sections":[{"h":"Sterowanie","body":["Doodler skacze automatycznie po wylądowaniu - ty tylko sterujesz lewo/prawo (z bezwładnością). Krawędzie są otwarte: wyjście w lewo wprowadza cię z powrotem po prawej.","Strzelaj w górę strzałką w górę lub [Space] ."]},{"h":"Platformy i dodatki","body":["- Zielona: normalna. Niebieska: rusza się. Brązowa: łamie się po nadepnięciu. Biała: znika po jednym skoku.","- Sprężyny dają super skok, czapka ze śmigłem unosi cię automatycznie w górę na chwilę (nietykalny).","- Potwory są śmiertelne przy kontakcie - zestrzelenie ich daje dodatkowe punkty."]},{"h":"Punktacja i wskazówki","body":["Wynik = osiągnięta wysokość; trudność rośnie wraz z wysokością.","- Zaplanuj, gdzie wylądować, zanim się odbijesz - brązowe platformy cię nie utrzymają.","- Wykorzystaj otwartą krawędź jako skrót do odległych platform."]}]},{"id":"2048","category":"games","game":"Game2048","title":"2048","keywords":["kafelki","przesuwanie","łączenie","liczby","gest","cofanie","na czas","bez końca","rozmiar","wznów","4096"],"sections":[{"h":"Sterowanie","body":["Strzałki lub [W] [A] [S] [D] przesuwają wszystkie kafelki naraz w jednym kierunku. Myszą lub touchpadem możesz też przeciągać: naciśnij, przeciągnij w wybranym kierunku i puść.","Przytrzymane klawisze się nie powtarzają - każdy ruch to osobne naciśnięcie. Polecenia wydane w trakcie animacji są zapamiętywane i wykonywane zaraz po niej.","[U] lub [Backspace] = cofnij, [R] lub [N] = nowa gra, [Tab] = powrót do ustawień. Te dodatkowe klawisze działają tylko wtedy, gdy sam nie przypisałeś ich do żadnej akcji."]},{"h":"Zasady","body":["Równe liczby, które się zderzą, łączą się w swoją sumę. Każdy kafelek łączy się najwyżej raz na ruch: 2, 2, 4, 4 przesunięte w lewo dają 4, 8.","Po każdym ważnym ruchu pojawia się nowy kafelek - zwykle 2, raz na dziesięć razy 4. Gdy żaden ruch nie jest już możliwy, gra się kończy.","Od 4096 kafelki mają własne kolory: od zieleni przez błękit i fiolet aż po karmin (131072); jeszcze większe są ciemne ze złotymi cyframi."]},{"h":"Ustawienia: rozmiar i tryb","body":["Rozmiar planszy od 3x3 do 8x8 - małe plansze są podchwytliwe, duże dają miejsce na długie łańcuchy.","- Klasyczny: celem jest 2048. Potem gra pyta, czy chcesz grać dalej - [Enter] kontynuuje, [N] zaczyna nową grę.","- Na czas: 3 minuty na jak najwięcej punktów. Zegar rusza z pierwszym ruchem, pasek pod planszą pokazuje pozostały czas.","- Bez końca: bez celu i bez przerw, aż zabraknie ruchów."]},{"h":"Cofanie","body":["Do wyboru w ustawieniach: wyłączone, 3 na grę lub bez limitu. Cofnięcie odwraca ostatni ruch razem z punktami - nawet tuż po końcu gry.","Gdy go użyjesz, gra liczy się jako rozegrana \"z cofaniem\": nie wlicza się do rekordu ani do osiągnięć za kafelki, a jej najlepszy wynik jest zapisywany osobno."]},{"h":"Zapis i wznawianie","body":["Trwająca gra zapisuje się automatycznie osobno dla każdego rozmiaru i trybu - po twoich ruchach i przy wychodzeniu z gry.","W ustawieniach pojawia się wtedy Wznów z punktami i ruchami zapisanej gry. Nowa gra usuwa ten zapis."]},{"h":"Punkty, najlepsze wyniki i rekord","body":["Każde połączenie daje wartość nowego kafelka. Kolumna informacji pokazuje punkty, najlepszy wynik, ruchy, największy kafelek, pozostałe cofnięcia i czas.","Najlepsze wyniki i największy kafelek są zapisywane dla każdego rozmiaru i trybu. Rekord gry 2048 liczy się tylko w 4x4 Klasycznym bez cofania."]},{"h":"Osiągnięcia","body":["- 2048!: stwórz kafelek 2048.","- 4096!: stwórz kafelek 4096.","Oba liczą się na planszach do 4x4 i tylko bez cofania - w każdym trybie."]},{"h":"Wskazówki","body":["- Zaparkuj największy kafelek w rogu i nigdy nie ruszaj tego rogu.","- Przesuwaj głównie w dwóch kierunkach - plansza pozostaje uporządkowana.","- W trybie na czas liczy się tempo: łącz wcześnie i trzymaj kafelki razem w jednym rogu."]}]},{"id":"minesweeper","category":"games","game":"MinesweeperGame","title":"Minesweeper","keywords":["miny","flagi","odkrywanie","chording","najlepszy czas"],"sections":[{"h":"Sterowanie","body":["Lewe kliknięcie odkrywa pole, prawe stawia flagę (opcjonalnie z cyklem znaku zapytania, [Q] w ustawieniach). [F] oznacza flagą pole pod kursorem, [R] restartuje.","Chording: kliknięcie spełnionej liczby (wszystkie flagi postawione) odkrywa naraz pozostałych sąsiadów."]},{"h":"Poziomy i punktacja","body":["Początkujący (9x9, 10 min), średniozaawansowany (16x16, 40) i ekspert (30x16, 99). Najlepszy czas dla każdego poziomu jest zapisywany.","Pierwsze kliknięcie jest zawsze bezpieczne - miny są rozmieszczane dopiero potem. Punkty = wartość bazowa poziomu minus sekundy."]},{"h":"Wskazówki","body":["- Zacznij od liczb na krawędzi otwartych obszarów - wzory są tam jednoznaczne.","- Jedynka w rogu z tylko jednym zakrytym sąsiadem to zawsze pewna flaga."]}]},{"id":"sudoku","category":"games","game":"SudokuGame","title":"Sudoku","keywords":["lamiglowka","liczby","notatki","poziomy","podpowiedzi","logika","killer","x-sudoku","sudoku dnia","gwiazdki","cofnij","kandydaci"],"sections":[{"h":"Warianty","body":["W ustawieniach wybierasz u góry wariant, a pod nim poziom trudności. Każdy wariant ma 4 poziomy trudności razy 100 stałych plansz, każda z jednym rozwiązaniem.","- Klasyczne: znane 9x9. 400 plansz jest takich samych jak przed aktualizacją - odhaczone poziomy zostają odhaczone.","- X-Sudoku: dodatkowo obie przekątne zawierają każdą cyfrę dokładnie raz (subtelnie zaznaczone).","- Killer: prawie bez podanych cyfr, za to z przerywanymi klatkami. Cyfry w klatce dają małą sumę w jej rogu i się nie powtarzają. Łatwy ma małe klatki i więcej podpowiedzi, Ekspert duże klatki.","- Mini 6x6: bloki 2x3 i tylko cyfry od 1 do 6, z bardzo dużymi polami.","- Sudoku dnia ([T] lub karta po prawej): jedna klasyczna plansza dziennie, taka sama dla wszystkich - także w przeglądarce. Trudność zależy od dnia tygodnia (poniedziałek łatwy, wtorek i środa normalny, czwartek, piątek i niedziela trudny, sobota ekspert). Rozwiązuj codziennie, by budować serię."]},{"h":"Sterowanie","body":["Pole wybierasz strzałkami, [W] [A] [S] [D] lub kliknięciem. Klawiatura cyfr po prawej działa w całości myszą i pod każdą cyfrą pokazuje, ile jej jeszcze brakuje.","- [1] do [9] wpisuje cyfrę, [0], Delete lub prawy klik wymazuje.","- [U] lub [Z] cofa, [Y] ponawia.","- [N] przełącza notatki, [C] automatycznie wpisuje wszystkich kandydatów, [H] daje podpowiedź.","- [M] koloruje pole znacznikiem (przełącznik \"Kolorowe znaczniki\" w ustawieniach).","- [R] zaczyna planszę od nowa, [Q] otwiera wybór poziomu, [A] po zakończeniu pokazuje rozwiązanie.","Wprowadzanie \"Najpierw cyfra\" (ustawienia, klawisz [I]): najpierw wybierz cyfrę, potem klikaj dowolnie wiele pól albo wpisz ją spacją.","W ustawieniach: [1] do [4] trudność, [V] wariant, [T] sudoku dnia, [F] limit błędów, strzałki + Enter uruchamiają poziom. Litery działają tylko wtedy, gdy nie są przypisane do żadnej akcji w opcjach."]},{"h":"Tryby i punkty","body":["Tryb gry określa pomoce i mnożnik punktów:","- Klasyczny x2.0: bez pomocy, jak na papierze.","- Notatki x1.5: plus notatki ołówkiem i automatyczni kandydaci.","- Komfort x1.0: błędy od razu na czerwono, zaznaczone konflikty i złe sumy klatek, poprawne wpisy się blokują.","- Wsparcie x0.7: dodatkowo do 3 podpowiedzi.","Każdy wpis jest od razu sprawdzany. Z limitem 3 błędów trzeci błąd kończy grę - cofnięcie nie usuwa błędu.","Punkty = (baza wariantu i trudności minus czas, błędy i podpowiedzi) razy mnożnik. Wszystkie warianty i sudoku dnia liczą się do rekordu."]},{"h":"Gwiazdki i zapis gry","body":["Każdy poziom daje do 3 gwiazdek: 1 za rozwiązanie, 2 bez błędów i podpowiedzi, 3 dodatkowo poniżej czasu docelowego danej trudności (widać go w informacjach o poziomie).","Wybór poziomu pokazuje gwiazdki, najlepszy czas i rozwiązane poziomy; zagięty róg oznacza rozpoczęte plansze.","Rozpoczęte plansze zapisują się same - przy wyjściu, przy powrocie do wyboru poziomu i regularnie w trakcie gry - i są kontynuowane przy kolejnym starcie. Jeśli zmienisz tryb, liczy się mniejszy mnożnik.","Osiągnięcia: \"Pogromca klatek\" za pierwsze sudoku Killer, \"Zbieracz gwiazd\" za 30 poziomów z 3 gwiazdkami."]},{"h":"Wskazówki","body":["- Zacznij od wierszy, kolumn i bloków, w których stoi już dużo cyfr.","- Zapisuj kandydatów parami: jeśli dwa pola jednej grupy mają tych samych dwóch kandydatów, znikają oni z reszty grupy.","- Killer: każdy wiersz, kolumna i blok daje 45. Jeśli klatki leżą w nich prawie w całości, reszta zdradza brakujące pole.","- Killer: niektóre sumy mają tylko jedną kombinację - 3 w dwóch polach to zawsze 1+2, 17 zawsze 8+9.","- X-Sudoku: przekątne to dwie dodatkowe grupy - sprawdzaj je wcześnie, często kryje się tam pierwsza cyfra."]}]},{"id":"frogger","category":"games","game":"FroggerGame","title":"Frogger","keywords":["żaba","droga","rzeka","zatoki","mucha","krokodyl"],"sections":[{"h":"Sterowanie","body":["Skacz pole po polu strzałkami lub [W] [A] [S] [D] .","- [R] restartuje, [S] otwiera ustawienia.","Po zakończeniu gry: [Enter] = ponów."]},{"h":"Droga, rzeka i zatoki","body":["Na dole 5 pasów ruchu z samochodami i ciężarówkami w naprzemiennych kierunkach - kontakt jest śmiertelny.","Wyżej 5 pasów rzeki: kłody i żółwie cię niosą; wpadnięcie do wody oznacza utonięcie. Żółwie okresowo się zanurzają na wyższych poziomach (miganie = ostrzeżenie).","Na górze czeka 5 zatok - zapełnienie wszystkich kończy poziom, potem wszystko przyspiesza.","- Dodatki: bonusowa mucha (+200) pojawia się na chwilę w pustych zatokach, krokodyle zajmują zatoki na wyższych poziomach (wylądowanie = śmierć), a pasek czasu na dole opróżnia się dla każdej żaby."]},{"h":"Punktacja","body":["Każdy nowo osiągnięty rząd daje 10 punktów, zatoka 50 plus 10 za każdą pozostałą sekundę.","Wszystkie 5 zatok daje 1000 punktów i następny poziom.","Przy 10 000 punktów dostajesz jednorazowe dodatkowe życie (start: 3 życia)."]},{"h":"Wskazówki","body":["- Planuj luki w ruchu z wyprzedzeniem o jeden pas, zamiast czekać na krawędzi.","- Wykorzystaj kłody dryfujące w stronę docelowej zatoki jako taksówkę.","- Ląduj wcześnie: bonus czasowy przewyższa objazd po muchę."]}]},{"id":"memory","category":"games","game":"MemoryGame","title":"Memory","keywords":["pary","karty","zapamiętywanie","pojedynek","odwracanie"],"sections":[{"h":"Sterowanie","body":["Odwracaj karty kliknięciem myszy - lub przesuwaj ramkę strzałkami/WASD i odwracaj klawiszem [Space] lub [Enter] .","- [R] tasuje nową rundę, [S] otwiera ustawienia.","Niedopasowana para pozostaje chwilę widoczna, a potem sama się odwraca z powrotem."]},{"h":"Plansze i pojedynek","body":["Trzy rozmiary planszy: 4x4 (8 par), 6x6 (18) i 8x6 (24) - motywy to kombinacje kształtu i koloru.","Solo każda odkryta kombinacja dwóch kart liczy się jako ruch; zegar tyka.","- Pojedynek (tryb wieloosobowy na ekranie przygotowania): odwracacie na zmianę, dopasowanie oznacza kolejny ruch - wygrywa ten, kto na koniec ma więcej par."]},{"h":"Punktacja","body":["Solo: baza zależna od rozmiaru planszy minus 15 za ruch i 2 za sekundę (minimum 100).","Pojedynek: pary zwycięzcy razy 100 trafiają na listę najlepszych wyników."]},{"h":"Wskazówki","body":["- Najpierw odwracaj nieznane karty - każda pokazuje ci motyw za darmo.","- Zapamiętuj motywy według ich grupy kolorów, to o połowę zmniejsza przestrzeń poszukiwań.","- W pojedynku nigdy nie odkrywaj świeżej pary dla przeciwnika."]}]},{"id":"solitaire","category":"games","game":"SolitaireGame","title":"Pasjans","keywords":["karty","klondike","spider","freecell","piramida","tripeaks"],"sections":[{"h":"Sterowanie","body":["Przeciągaj karty myszą (przeciągnij i upuść) lub przesuwaj je kliknięciami; prawe kliknięcie wysyła wierzchnią kartę na stos bazowy (Klondike/FreeCell).","- [U] cofa dowolną liczbę ruchów, [R] rozdaje nowe rozdanie, [S] otwiera ustawienia.","[Space] lub [Enter] obsługuje talię (dobieranie/rozdawanie)."]},{"h":"Pięć wariantów","body":["- Klondike: klasyczny pasjans - cztery stosy bazowe od asa do króla, tableau malejące w naprzemiennych kolorach; opcja: dobieranie 1 lub 3.","- Spider: 10 kolumn, 104 karty - kompletne sekwencje od króla do asa w jednym kolorze znikają; opcja: 1, 2 lub 4 kolory.","- FreeCell: wszystko odkryte, 4 wolne komórki; superruchy są ograniczone liczbą wolnych komórek i pustych kolumn.","- Piramida: usuwaj pary sumujące się do 13, król liczy się sam; 2 ponowne rozdania.","- TriPeaks: zawsze o jedną wartość wyżej lub niżej niż stos odrzuconych (as i król się łączą) - długie łańcuchy dają punkty combo."]},{"h":"Punktacja","body":["Klondike: +10 za kartę na stosie bazowym, +5 za odkrytą kartę, bonus czasowy za wygraną. FreeCell: +10 za kartę na stosie bazowym plus bonus czasowy.","Spider: 500 minus ruchy plus 100 za każdą ukończoną sekwencję. Piramida: +5 za kartę, +500 za oczyszczenie.","TriPeaks: 10 razy combo za kartę - talia resetuje combo; +500 za oczyszczenie."]},{"h":"Opcje","body":["Dobieranie 3 (Klondike) i liczba kolorów w Spiderze są zapisywane na stałe.","Cofanie jest nieograniczone i darmowe - eksperymentuj do woli.","Wszystkie warianty dzielą jedną listę najlepszych wyników."]},{"h":"Wskazówki","body":["- Uwalniaj asy i dwójki jak najwcześniej (Klondike/FreeCell).","- Trzymaj jedną kolumnę pustą - to twoje najważniejsze narzędzie (Spider/FreeCell).","- W Piramidzie policz dostępne pary do 13, zanim ruszysz talię."]}]},{"id":"aimtrainer","category":"games","game":"AimTrainerGame","title":"Aim Trainer","keywords":["celowanie","celownik","refleks","3d","kosmos","strzelanie"],"sections":[{"h":"Sterowanie","body":["Mysz steruje kamerą bezpośrednio jak w strzelance: każdy ruch natychmiast obraca widok o tę wartość (kursor jest niewidocznie przechwytywany wewnątrz okna). [Esc] wstrzymuje i zwalnia mysz. Obrót w poziomie jest nieograniczony, góra/dół zatrzymuje się na 60 stopniach.","Lewe kliknięcie strzela dokładnie przez środek ekranu (krótki czas odnowienia między strzałami).","- [+] i [-] zmieniają czułość (nawet w trakcie gry), [E] kończy sesję chill."]},{"h":"Tryby","body":["- Precyzja (60 s): zawsze 3 kule naraz - zestrzelenie jednej natychmiast tworzy nową; na koniec dodawany jest bonus za celność.","- Refleks (30 celów): cele pojawiają się pojedynczo i kurczą się po chwili - liczy się czas reakcji, statystyki na koniec.","- Ruchome cele (60 s): kule dryfują po torach (wahają się, krążą, kołyszą) - kolejne trafienia podnoszą mnożnik combo.","- Chill (bez końca): brak licznika czasu, brak kary za pudło - po prostu odpręż się i strzelaj; wynik jest zapisywany po powrocie do menu."]},{"h":"Punktacja","body":["Precyzja: 100 punktów za trafienie plus bonus za odległość; na koniec celność do kwadratu razy 1500 na dodatek.","Refleks: im szybsza reakcja, tym więcej punktów (1000 minus milisekundy, co najmniej 50).","Ruchome cele: 80 punktów razy mnożnik combo (do x4 przy 12 trafieniach z rzędu) - pudło resetuje combo.","Chill: 50 punktów razy mnożnik; combo zanika dopiero po 5 sekundach bez trafienia."]},{"h":"Motywy","body":["- Kosmos (domyślny): pełna sfera gwiazd, czarna dziura z jasno świecącym pierścieniem i odległa planeta.","- Neon: arena w stylu synthwave ze świecącą siatką podłogi i pasiastym słońcem.","- Strzelnica: kryta hala z torami, lampami i klasycznymi tarczami. Motyw i regulowane rozmycie ruchu (od 0 do 80 procent, klawisz [B] lub przyciski w ustawieniach) są zapisywane."]},{"h":"Wskazówki","body":["- Małe, spokojne ruchy myszą trafiają lepiej niż gwałtowne machnięcia - widok podąża 1:1.","- Niska czułość do precyzji, wyższa do refleksu i ruchomych celów.","- Odległe cele mają niewielki margines tolerancji - trzymaj stabilnie zamiast nadmiernie korygować."]}]},{"id":"connect4","category":"games","game":"ConnectFourGame","title":"Cztery w rzędzie","keywords":["cztery","rząd","krążki","kolumny","ai","strategia"],"sections":[{"h":"Jak grać","body":["Dwa kolory na zmianę wrzucają krążki do jednej z 7 kolumn; każdy krążek spada na najniższe wolne pole. Kto pierwszy ustawi cztery w linii - poziomo, pionowo lub po przekątnej - wygrywa rundę.","W trybie jednoosobowym grasz przeciwko AI (trzy poziomy siły w ustawieniach); w trybie dla 2 graczy gracie na zmianę jedną myszą lub klawiaturą.","Gracz rozpoczynający zmienia się co rundę. [Enter] rozpoczyna następną rundę, [S] wraca do ustawień."]},{"h":"Sterowanie","body":["- Mysz: najedź na kolumnę (krążek podglądu pokazuje miejsce) i kliknij.","- Klawiatura: [Left] [Right] wybierają kolumnę, upuszczasz klawiszem [Down], [Space] lub [Enter].","- Wybór bezpośredni: liczby [1] do [7] wrzucają prosto do danej kolumny."]},{"h":"Poziomy siły AI","body":["Łatwy celowo przeocza niektóre zagrożenia i czasem gra tylko drugi najlepszy ruch - świetny do nauki. Średni planuje kilka ruchów naprzód i niezawodnie blokuje.","Trudny przeszukuje znacznie głębiej i natychmiast karze każdy błąd - tutaj wygrywają tylko podwójne zagrożenia."]},{"h":"Punktacja i wskazówki","body":["Każda wygrana przeciwko AI daje jeden punkt; najlepszy wynik to najwięcej zwycięstw w jednej sesji. W trybie dla 2 graczy nie ma punktacji.","- Środkowa kolumna jest najsilniejsza: przechodzi przez nią większość czwórek.","- Buduj podwójne zagrożenia (dwie otwarte trójki naraz) - przeciwnik może zablokować tylko jedno z nich."]}]},{"id":"tanks","category":"games","game":"TankDuelGame","title":"Pojedynek czołgów","keywords":["czołg","pojedynek","rykoszet","arena","power-up","2 graczy"],"sections":[{"h":"Jak grać","body":["1 na 1 na arenie ze ścianami: trafienie przeciwnika daje rundę - kto pierwszy zdobędzie 5 rund, wygrywa mecz.","Strzały odbijają się od ścian raz (rykoszet) i znikają przy drugim kontakcie. Uwaga: odbity strzał może trafić także ciebie.","Graj przeciwko AI (trzy poziomy siły) lub we dwóch na jednej klawiaturze. Po meczu: [Enter] = rewanż, [S] = ustawienia."]},{"h":"Sterowanie","body":["- Gracz 1: [W] [S] jadą do przodu i do tyłu, [A] [D] skręcają, [Space] strzela.","- Gracz 2: strzałki jadą i skręcają, [Enter] strzela. Przypisania są zgodne z opcjami.","- Naraz istnieją najwyżej 4 twoje strzały, z krótkim przeładowaniem pomiędzy."]},{"h":"Power-upy","body":["- Szybki ogień: 8 sekund niemal bez przeładowania.","- Tarcza: pochłania dokładnie jedno trafienie (pierścień wokół czołgu).","- Potrójny strzał: następne 5 strzałów rozchodzi się w trzech kierunkach. Power-upy pojawiają się co kilka sekund na arenie i wygasają po 12 sekundach."]},{"h":"Areny i AI","body":["Cztery areny do wyboru: Otwarta (bez osłon), Krzyż, Filary i Labirynt - albo Losowa, która zmienia arenę co rundę.","Łatwe AI jeździ bez celu i słabo celuje; średnie ściga cię i uskakuje na bok.","Trudne AI trzyma dystans, prowadzi strzały z wyprzedzeniem twojego ruchu, a nawet celowo odbija strzały od ścian."]},{"h":"Punktacja i wskazówki","body":["Przeciwko AI zdobywasz punkty za wygrany mecz: więcej za wyższe poziomy siły i czyste zwycięstwa; punkty sumują się między rewanżami. W trybie dla 2 graczy nie ma punktacji.","- Wykorzystuj ściany: odbijanie strzałów za rogi trafia, nie wystawiając cię na strzał."]}]},{"id":"blackjack","category":"games","game":"BlackjackGame","title":"Blackjack","keywords":["karty","kasyno","21","żetony","krupier","zakład","bank lamy"],"sections":[{"h":"Jak grać","body":["Cel: podejść bliżej 21 niż krupier, nie przekraczając tej wartości. Karty z liczbami liczą się według nominału, figury 10, as 11 lub 1.","Gra używa buta z 4 talii; krupier dobiera do 16 i staje na każdym 17.","Najpierw postaw zakład (przyciski żetonów lub klawisze [1] do [4], [Backspace] go czyści), potem rozdaj klawiszem [Enter]."]},{"h":"Akcje","body":["- Dobierz [H]: dobierz kolejną kartę.","- Stój [S]: zachowaj obecną sumę.","- Podwój [D]: podwój zakład, weź dokładnie jedną kartę, potem automatycznie stój - tylko przy dwóch pierwszych kartach.","- Rozdziel [X]: rozdziel dwie karty o równej wartości na dwie ręce (raz na rundę; rozdzielone asy dostają tylko po jednej karcie)."]},{"h":"Wypłaty","body":["- Blackjack (as + karta o wartości dziesięć) płaci 3:2.","- Zwykła wygrana płaci 1:1, remis (push) zwraca twój zakład.","- Przekroczenie lub przegrana: zakład przepada. Jeśli krupier pokazuje asa lub 10, natychmiast sprawdza, czy ma blackjacka."]},{"h":"Żetony Lamy","body":["Blackjack, Poker i Casino dzielą jedno konto w Banku Lamy: zaczynasz z 1000 żetonów Lamy, a stan konta jest trwale zapisywany.","Stawka jest pobierana od razu przy rozdaniu - kto opuści trwające rozdanie, traci ją.","Rekord to najwyższy stan twojego bilansu w blackjacku: 1000 plus wszystko, co wygrałeś i przegrałeś w blackjacku. Wygrane w ruletce, na automacie czy w pokerze się tu nie liczą.","Poniżej 10 żetonów jesteś bankrutem: [Enter] bierze kredyt z banku i uzupełnia konto do 1000. Kredyty nie liczą się do bilansu."]},{"h":"Wskazówki","body":["- Podstawowa strategia: przy odkrytej karcie 7 lub wyższej dobieraj do 17; przy 4 do 6 stój wcześnie - krupier często tam przebija.","- Zawsze rozdzielaj asy i ósemki, nigdy nie rozdzielaj dziesiątek."]}]},{"id":"tunnelracer","category":"games","game":"TunnelRacerGame","title":"Tunnel Racer","keywords":["tunel","wyścig","3d","neon","unik","bez końca"],"sections":[{"h":"Jak grać","body":["Lecisz przez zakręcającą neonową rurę, unikając belek, bloków i bramek pierścieniowych - jedno trafienie i przejazd się kończy.","Złote monety unoszą się w przerwach; dają dodatkowe punkty i zwykle wyznaczają bezpieczną linię.","Bramki pierścieniowe mają dokładnie jeden otwór: przeciśnij się przez niego zamiast robić unik."]},{"h":"Tryby","body":["- Bez końca: prędkość stale rośnie, a przerwy się zwężają - jak daleko dotrzesz? Kolizja kończy przejazd i zapisuje najlepszy wynik.","- Poziomy: 30 stałych tras z metą, od spokojnych po brutalne. Ukończone poziomy są odhaczane; punkty sesji się sumują."]},{"h":"Sterowanie","body":["- Klawisze (domyślnie): [W] [A] [S] [D] lub strzałki przesuwają statek po rurze.","- Mysz: włączasz w ustawieniach klawiszem [C] - bezpośrednie sterowanie 1:1, kursor jest przechwytywany, a [Esc] go zwalnia.","- [B] przełącza rozmycie ruchu w krokach po 10 procent (od 0 do 80, zapisywane).","- W trybie poziomów: [R] ponawia po kolizji, [S] otwiera wybór."]},{"h":"Punktacja","body":["- Bez końca: 10 punktów za metr plus 50 za monetę.","- Poziomy: 1000 za metę, 50 za monetę i bonus czasowy, gdy pobijesz czas referencyjny.","Najlepszy wynik w trybie poziomów to twoja najlepsza suma z sesji - granie kilku poziomów z rzędu się opłaca."]},{"h":"Wskazówki","body":["- Obserwuj pierścienie z daleka: rura zapowiada zakręt na tyle wcześnie, by kontrować.","- Trzymaj się blisko środka, kiedy to możliwe - stamtąd osiągalna jest każda przerwa."]}]},{"id":"labyrinth","category":"games","game":"LabyrinthGame","title":"Labirynt 3D","keywords":["labirynt","maze","raycaster","kule","wyjście","3d"],"sections":[{"h":"Jak grać","body":["50 labiryntów generowanych z ziarna, które rosną z każdym poziomem. Znajdź zielone pulsujące wyjście - zawsze znajduje się w punkcie najbardziej oddalonym od startu.","Niebieskie kule unoszą się po labiryncie; każda zebrana kula daje punkty bonusowe.","Ukończone poziomy są odhaczane w wyborze; [Enter] na mecie od razu rozpoczyna następny."]},{"h":"Widoki","body":["- Pierwsza osoba (3D): widok w stylu Wolfenstein z rozglądaniem się myszą - w samym środku zamiast z góry.","- Z góry (2D): klasyczna mapa z lotu ptaka, bez żadnego przechwytywania myszy. Przełączasz w ustawieniach klawiszem [V]; wybór jest zapisywany."]},{"h":"Sterowanie","body":["- Pierwsza osoba: [W] [S] do przodu i do tyłu, [A] [D] krok w bok, mysz obraca widok - albo obracaj klawiszami [Q] i [E].","- [M] przełącza minimapę, [Esc] wstrzymuje i zwalnia mysz.","- Z góry: [W] [A] [S] [D] lub strzałki chodzą w kierunkach świata."]},{"h":"Punktacja","body":["- Dotarcie do wyjścia: 500 punktów.","- Za kulę: 100 dodatkowych punktów.","- Plus bonus czasowy, gdy pobijesz czas referencyjny poziomu; punkty sesji sumują się do najlepszego wyniku."]},{"h":"Wskazówki","body":["- Reguła prawej ręki: trzymanie się cały czas tej samej ściany na pewno doprowadzi do wyjścia.","- Kule mniej więcej wyznaczają drogę do wyjścia - ich zbieranie zwykle oznacza, że jesteś na dobrej drodze."]}]},{"id":"reversi","category":"games","game":"ReversiGame","title":"Reversi","keywords":["reversi","othello","krążki","odwracanie","rogi","ai"],"sections":[{"h":"Jak grać","body":["Reversi (Othello) rozgrywa się na planszy 8x8. Kładziesz krążek tak, aby jeden lub więcej krążków przeciwnika zostało uwięzionych w linii prostej między nowym krążkiem a innym krążkiem twojego koloru - poziomo, pionowo lub po przekątnej. Wszystkie uwięzione krążki zmieniają się na twój kolor.","Ruch jest dozwolony tylko wtedy, gdy odwraca co najmniej jeden krążek. Jeśli nie masz dozwolonego ruchu, twoja kolej jest pomijana automatycznie. Gdy żaden z graczy nie może się ruszyć, gra się kończy i wygrywa ten, kto ma więcej krążków.","W trybie jednoosobowym ty (Czarne) grasz przeciwko AI; w trybie dwuosobowym Czarne i Białe grają na zmianę."]},{"h":"Sterowanie","body":["- Mysz: kliknij puste pole. Dozwolone pola są oznaczone małą kropką.","- Klawiatura: strzałki (lub twoje klawisze ruchu) przesuwają ramkę wyboru, [Space] lub [Enter] kładzie krążek.","- Po rundzie: [Enter] = nowa runda, [S] = powrót do ustawień (tylko jeden gracz)."]},{"h":"Siła AI i wskazówki","body":["Łatwy gra głównie losowo, Średni przewiduje kilka ruchów, Trudny przeszukuje głębiej i wysoko ceni rogi.","- Rogi są na wagę złota: krążka w rogu nigdy nie da się już odwrócić.","- Uważaj na pola obok rogu - często oddają one róg przeciwnikowi.","- Posiadanie mniejszej liczby krążków, ale większej mobilności w środkowej fazie gry, jest często lepsze niż posiadanie wielu."]},{"h":"Punktacja","body":["Każda wygrana przeciwko AI jest warta jeden punkt; najlepszy wynik to najwięcej zwycięstw w sesji. Gry dwuosobowe nie są punktowane."]}]},{"id":"kniffel","category":"games","game":"KniffelGame","title":"Yahtzee","keywords":["yahtzee","kniffel","kości","strit","full","wynik"],"sections":[{"h":"Jak grać","body":["Masz 5 kości i do 3 rzutów na turę. Po każdym rzucie możesz zachować dowolne kości i przerzucić tylko resztę. Następnie zapisujesz wynik w dokładnie jednej z 13 kategorii.","Każdą kategorię można wykorzystać tylko raz. Jeśli nic nie pasuje, skreślasz jedną za 0 punktów. Po 13 turach arkusz jest pełny i gra się kończy.","Tryb jednoosobowy to pogoń za najlepszym wynikiem, czyli najwyższą sumą; w trybie dwuosobowym wypełniacie dwa arkusze na zmianę - wygrywa wyższa suma."]},{"h":"Kategorie","body":["Górna sekcja (Jedynki do Szóstek): liczy oczka danej liczby. Jeśli twoja górna sekcja sumuje się do co najmniej 63, zdobywasz bonus 35 punktów.","- Trójka/Czwórka: suma wszystkich kości, jeśli co najmniej 3 wzgl. 4 są takie same.","- Full = 25 (trójka plus para), Mały strit = 30 (cztery po kolei), Duży strit = 40 (pięć po kolei), Yahtzee = 50 (pięć jednakowych), Szansa = suma wszystkich kości (zawsze dozwolona)."]},{"h":"Sterowanie","body":["- [Space] lub przycisk Rzuć przerzuca kości, które nie są zatrzymane.","- Kliknij kość lub naciśnij [1] do [5], aby zatrzymać lub zwolnić tę kość.","- Kliknij kategorię lub wybierz ją strzałkami i naciśnij [Enter], aby ją zapisać.","- Po grze: [Enter] restartuje."]},{"h":"Wskazówki","body":["- Zdobądź bonus 63 punktów z górnej sekcji wcześnie - piątki i szóstki są szczególnie cenne.","- Użyj Szansy, aby uratować zły rzut; skreśl Yahtzee lub strita, jeśli nic nie wychodzi."]}]},{"id":"wordle","category":"games","game":"WordleGame","title":"Wordle","keywords":["wordle","słowo","zgadywanie","litery","zielony","żółty","slownik","słowo dnia","dordle","quordle","statystyki","udostępnij","daltonizm","długość"],"sections":[{"h":"Jak grać","body":["Odgadnij ukryte słowo. Po każdej próbie pola zmieniają kolor: zielony = właściwa litera na właściwym miejscu, żółty = litera jest w słowie, ale gdzie indziej, szary = litery nie ma w słowie.","Powtórzone litery są liczone poprawnie: litera jest oznaczona na żółto lub zielono tylko tyle razy, ile razy naprawdę występuje w rozwiązaniu.","Każda próba musi być prawdziwym słowem - sprawdzana jest na liście słów wybranego języka i długości (od 4000 do 19 000 dozwolonych słów, zależnie od języka i długości). Inne słowa są odrzucane: wiersz na chwilę się trzęsie, a próba się nie liczy. Rozwiązania to zawsze popularne słowa tego samego języka - bez nazw własnych i obraźliwych słów."]},{"h":"Tryby","body":["Bez końca: słowo za słowem, na każde 6 prób. Pierwsze słowo, którego nie odgadniesz, kończy grę.","Słowo dnia: jedno słowo dziennie w 6 próbach - dla wszystkich takie samo w każdym języku i długości, na PC i w przeglądarce. Rozpoczęte słowo dnia jest zapisywane; potem gra pokazuje wynik, statystyki i odliczanie do następnego słowa. Seria rośnie tylko wtedy, gdy grasz codziennie.","Dordle: dwa słowa naraz w 7 próbach - każda próba liczy się dla obu plansz. Klawisze klawiatury ekranowej są podzielone: lewa połowa to plansza 1, prawa to plansza 2.","Quordle: cztery słowa naraz w 9 próbach. Klawisze są podzielone na ćwiartki i pokazują kolory wszystkich czterech plansz."]},{"h":"Ustawienia przed startem","body":["Przed każdą grą pojawia się ekran ustawień - obok widać twoje statystyki dla wybranego trybu i długości.","- Długość słowa: 4, 5, 6 lub 7 liter, każda z własnymi listami słów.","- Tryb trudny: odkryte wskazówki trzeba wykorzystać - zielone litery zostają na miejscu, żółte muszą pojawić się ponownie. W Dordle i Quordle próba musi pasować do wskazówek co najmniej jednej nierozwiązanej planszy.","- Tryb dla daltonistów: pomarańczowy zamiast zielonego i niebieski zamiast żółtego - także w udostępnianym wyniku.","Wszystkie ustawienia są od razu zapisywane."]},{"h":"Sterowanie","body":["- Wpisuj litery A-Z, [Backspace] usuwa ostatnią, [Enter] sprawdza wiersz.","- Klawiatura ekranowa działa też myszą: QWERTZ dla niemieckiego, czeskiego, słoweńskiego i chorwackiego, AZERTY dla francuskiego, w pozostałych QWERTY. Jej klawisze kolorują się według tego, co już wiesz.","- Ikona suwaków w prawym górnym rogu wraca do ekranu ustawień.","- W ustawieniach: [4] do [7] lub [Lewo] / [Prawo] = długość, [H] = tryb trudny, [F] = tryb dla daltonistów, [Enter] = start.","- Po grze: [Enter] = jeszcze raz, [C] = udostępnij wynik, [S] = ustawienia. [Spacja] ukrywa wynik, aby obejrzeć plansze."]},{"h":"Punktacja i statystyki","body":["Bez końca: każde odgadnięte słowo daje punkty - im mniej prób, tym więcej (od 10 do 60). Do rekordu liczy się tylko tryb Bez końca z 5 literami; pozostałe długości mają własne najlepsze wyniki.","Statystyki są zapisywane osobno dla języka, długości i trybu: rozegrane gry, procent wygranych, aktualna i najlepsza seria oraz rozkład prób jako wykres słupkowy - słupek ostatniej wygranej świeci."]},{"h":"Udostępnianie wyniku","body":["[C] lub przycisk Udostępnij kopiuje wynik do schowka jako siatkę emoji - bez zdradzania rozwiązania - więc możesz go wkleić do dowolnego czatu. Gwiazdka * za wynikiem oznacza tryb trudny."]},{"h":"Osiągnięcia","body":["- Jasnowidz: odgadnij słowo w maksymalnie 2 próbach.","- Słowny nawyk: rozwiąż 7 słów dnia z rzędu.","- Poczwórny geniusz: rozwiąż wszystkie cztery słowa w Quordle."]},{"h":"Wskazówki","body":["- Zacznij od słowa z wieloma różnymi, częstymi literami.","- Szarymi literami wykluczaj możliwości, a żółte przestawiaj na nowe miejsca.","- W Dordle i Quordle najpierw zgaduj słowa, które dają wskazówki dla kilku plansz naraz."]}]},{"id":"trex","category":"games","game":"TRexRunnerGame","title":"T-Rex Runner","keywords":["trex","dino","biegacz","skok","kucanie","bez końca"],"sections":[{"h":"Sterowanie","body":["Zacznij bieg klawiszem [Space] lub [Up] - dino biegnie potem automatycznie.","- Skok: dotknij [Space]/[Up] dla małych podskoków, przytrzymaj dla wyższych skoków.","- Kucanie: przytrzymaj [Down] - w powietrzu sprawia, że spadasz szybciej."]},{"h":"Przeszkody","body":["Kaktusy pojawiają się pojedynczo lub w grupach na ziemi - przeskakuj je.","Pterodaktyle pojawiają się na trzech wysokościach: wysoko = kucnij, nisko/średnio = skacz.","Prędkość stale rośnie; co 100 punktów słychać sygnał dźwiękowy i pojawia się krótkie mignięcie."]},{"h":"Opcje i wskazówki","body":["Przełączaj na ekranie startowym (zapisywane): [1]-[3] trudność, [N] dzień/noc, [C] skórka.","- Krótkie dotknięcie oszczędza wysokość na szybkie podwójne przeszkody.","- Po kraksie kontynuuj od razu klawiszem [Enter]/[Space]."]}]},{"id":"dame","category":"games","game":"DameGame","title":"Warcaby (Dame)","keywords":["warcaby","warcaby angielskie","dame","bicie obowiązkowe","latająca damka","plansza"],"sections":[{"h":"Warianty","body":["Wybierane w ustawieniach - każdy z 1 graczem przeciw AI lub 2 graczami lokalnie:","- Warcaby niemieckie 8x8: pionki biją do przodu i do tyłu, damka lata na dowolną odległość.","- Warcaby międzynarodowe 10x10: większa plansza, bicie obowiązkowe z regułą maksimum (najdłuższe bicie jest obowiązkowe).","- Warcaby angielskie 8x8: pionki biją tylko do przodu, damka rusza się tylko o jedno pole."]},{"h":"Zasady i sterowanie","body":["Bicia są obowiązkowe: jeśli istnieje bicie, musisz je wykonać - bijące pionki są obrysowane na czerwono.","Kliknij pionek, potem pole docelowe; wielokrotne bicie wykonuj krok po kroku.","Klawiatura: [Arrows]/[WASD] przesuwają ramkę, [Space]/[Enter] wybiera.","Pionek, który dotrze do przeciwległego rzędu, staje się damką (korona)."]},{"h":"AI i punktacja","body":["Tryb jednoosobowy oferuje trzy poziomy siły AI (minimax + alpha-beta), wybierasz je w ustawieniach klawiszami [<]/[>].","Najlepszy wynik liczy twoje zwycięstwa przeciwko AI w tej sesji; tryb wieloosobowy nie jest punktowany.","Po grze: [Enter] nowa runda, [S] powrót do ustawień."]}]},{"id":"poker","category":"games","game":"PokerGame","title":"Poker","keywords":["poker","holdem","texas","video poker","dobierany","żetony","ciemne","bank lamy"],"sections":[{"h":"Tryby","body":["Wybierz wariant na ekranie przygotowania:","- Texas Hold'em: przeciwko 1-3 przeciwnikom AI, z żetonem rozdającego, ciemnymi i czterema rundami licytacji (preflop, flop, turn, river).","- 5 Card Draw: jeden na jednego przeciw AI - wymiana kart raz, dwie rundy licytacji.","- Video Poker (Jacks or Better): solo przeciwko tabeli wypłat."]},{"h":"Akcje","body":["Podczas licytacji: [F] pas, [C] czekaj/sprawdź, [R] podbij, [A] all-in - albo klikaj przyciski.","Przy wymianie/zatrzymywaniu: kliknij karty lub naciśnij [1]-[5], potem [Enter], aby dobrać.","[Enter]/[Space] rozdaje następne rozdanie."]},{"h":"Żetony Lamy","body":["Gra toczy się o żetony Lamy z Banku Lamy - wspólne konto z Blackjackiem i Casino (start 1000, trwale zapisywane).","Na początku rozdania twoje konto leży na stole jako stos; to, co trafia do puli, jest od razu pobierane. Jeśli opuścisz stół w trakcie rozdania, twoja część puli przepada - reszta wraca na konto.","Rekord to najwyższy stan twojego bilansu w pokerze: 1000 plus wszystko, co wygrałeś i przegrałeś w pokerze. Wygrane w innych grach się tu nie liczą.","Bankructwo (mniej niż duża ciemna 20, w Video Pokerze mniej niż 10) = kredyt z banku jednym kliknięciem, konto znów ma 1000."]},{"h":"Układy","body":["Ranking układów: Wysoka karta < Para < Dwie pary < Trójka < Strit < Kolor < Full < Kareta < Poker < Poker królewski."]}]},{"id":"chess","category":"games","game":"ChessGame","title":"Szachy (Chess)","keywords":["szachy","chess","mat","roszada","en passant","ai","chess960","zadania","zegar","pgn"],"sections":[{"h":"Jak się gra","body":["Szachy z pełnym zestawem zasad: wszystkie ruchy bierek, roszada krótka i długa, bicie w przelocie oraz promocja pionka na hetmana, wieżę, gońca lub skoczka.","Partia kończy się matem, poddaniem, przekroczeniem czasu albo remisem - przez pat, regułę 50 posunięć, trzykrotne powtórzenie, niewystarczający materiał lub zgodę.","Trzy tryby: partia z AI, 2 graczy przy jednym komputerze (tylko wersja na komputer) i zadania.","Obok szachownicy widać graczy z zegarem, zbitymi bierkami i bilansem materiału (np. +2), a pod nimi listę ruchów w notacji standardowej - przewijaną kółkiem myszy."]},{"h":"Sterowanie","body":["- Mysz: kliknij swoją bierkę albo przeciągnij ją od razu na pole docelowe. Możliwe pola, ostatni ruch i szachowany król są podświetlone.","- Klawiatura: [Strzałki] lub [WASD] przesuwają ramkę, [Spacja] albo [Enter] wybiera i wykonuje ruch.","- Roszada: przesuń króla na pole docelowe albo na własną wieżę. Przy promocji pojawia się wybór bierki.","- Przyciski: [U] lub [Backspace] cofnij, [H] podpowiedź, [F] obróć szachownicę, [O] zaproponuj remis, [X] poddaj się.","- Po partii: [Enter] nowa partia (kolory się zmieniają), [S] ustawienia, [P] zapisz partię jako PGN."]},{"h":"Ustawienia: siła, zegar i Chess960","body":["Sześć poziomów AI od Początkującego do Mistrza: Początkujący gra losowo, poziomy średnie celowo urozmaicają grę, Trudny i Mistrz liczą z iteracyjnym pogłębianiem, tablicą transpozycji i przeszukiwaniem spokojnych pozycji oraz znają popularne debiuty. AI myśli małymi porcjami na klatkę - gra nigdy się nie zacina.","Zegar: bez, 1+0, 3+2, 5+0 lub 10+5 (minuty + sekundy dodawane za ruch). Rusza po pierwszym ruchu. Kto przekroczy czas, przegrywa - chyba że przeciwnik nie może już w ogóle dać mata, wtedy jest remis.","Chess960: jedno z 960 losowych ustawień początkowych, jego numer widać nad listą ruchów. Przy roszadzie król i tak staje na g lub c, a wieża na f lub d; pola pomiędzy muszą być wolne, a król nie może przechodzić przez szach."]},{"h":"Pomoc, remis i punkty","body":["Cofnięcie zabiera przeciw AI dwa półruchy, podpowiedź pokazuje najlepszy ruch niebieską strzałką. Obie rzeczy sprawiają, że partia jest „z pomocą”: wygrana nie liczy się wtedy do rekordu, statystyk ani osiągnięć.","Propozycja remisu: AI przyjmuje ją tylko wtedy, gdy ocenia swoją pozycję co najwyżej jako równą - inaczej odmawia, a kolejną propozycję możesz złożyć dopiero po kilku ruchach.","Rekord liczy twoje zwycięstwa bez pomocy nad AI w tej sesji. Wygrana z Mistrzem (poziom 6) odblokowuje osiągnięcie „Arcymistrz”.","Po partii możesz zapisać ją jako plik PGN (w przeglądarce: pobranie i schowek) i odtworzyć w dowolnym programie szachowym."]},{"h":"We dwoje","body":["Białe i czarne grają na zmianę przy jednym komputerze; zegar i Chess960 działają jak w grze z AI. Z opcją „Obracaj szachownicę po każdym ruchu” plansza po każdym ruchu obraca się do strony, która ma ruch.","Propozycja remisu pyta przeciwnika, poddanie dotyczy strony na posunięciu. Tryb dwuosobowy nie jest punktowany i nie ma go w wersji przeglądarkowej."]},{"h":"Zadania","body":["200 zadań w pięciu poziomach: Mat w 1, Mat w 2, Mat w 3, Taktyka I i Taktyka II - po 40, od łatwych do trudnych. Rozwiązane dostają znaczek, a postęp jest zapisywany.","Najpierw przeciwnik wykonuje swój ostatni ruch, potem twoja kolej. Błędny ruch zostaje cofnięty po krótkiej wskazówce, a odpowiedź przeciwnika pojawia się sama. W zadaniach matowych liczy się każdy ruch, który od razu daje mata.","- [H] pokaż rozwiązanie (zadanie nie liczy się wtedy jako rozwiązane), [U] jeszcze raz, [N] następne zadanie, [M] powrót do listy.","25 rozwiązanych zadań odblokowuje osiągnięcie „Łamigłówka”.","Źródło: zadania pochodzą z wolnej bazy zadań lichess.org (CC0) i zostały sprawdzone naszym własnym silnikiem - dziękujemy, Lichess!"]},{"h":"Wskazówki","body":["- Rozwijaj bierki wcześnie, wykonaj roszadę i ustaw wieże na otwartych liniach.","- W zadaniach najpierw szukaj szachów, bić i zagrożeń.","- Z zegarem nie myśl za długo - dodatek czasu w 3+2 i 10+5 ratuje niejedną końcówkę."]}]},{"id":"muehle","category":"games","game":"MuehleGame","title":"Młynek (Nine Men's Morris)","keywords":["młynek","mlynek","morris","podwójny młynek","latanie","ai"],"sections":[{"h":"Trzy fazy","body":["- Ustawianie: obaj gracze kładą na zmianę swoje dziewięć pionów na wolnych punktach.","- Ruch: potem pion przesuwa się wzdłuż linii na sąsiedni wolny punkt.","- Latanie: kto ma już tylko trzy piony, może skoczyć na dowolny wolny punkt. Tę zasadę można wyłączyć w ustawieniach.","Przegrywa ten, komu zostanie mniej niż trzy piony albo nie ma już ruchu."]},{"h":"Młynki i sterowanie","body":["Trzy własne piony w linii tworzą młynek: natychmiast zdejmujesz jeden pion przeciwnika. Piony z zamkniętego młynka przeciwnika są nietykalne, dopóki są inne - dozwolone cele są podświetlone.","- Mysz: kliknij wolny punkt. Przy ruchu wybierz najpierw swój pion, potem cel; możliwe cele się zapalają.","- [Esc] cofa przypadkowy wybór.","- Po rundzie: [Enter] nowa runda, [S] powrót do ustawień (tylko jeden gracz)."]},{"h":"AI i punkty","body":["Trzy poziomy siły w oparciu o minimax z odcięciem alfa-beta. Oceniane są materiał, zamknięte młynki, ruchliwość i otwarte podwójne młynki - z inną wagą w każdej fazie; poziom łatwy myli się celowo.","Wynik liczy zwycięstwa nad AI w tej sesji; tryb wieloosobowy nie jest punktowany.","Wskazówka: podwójny młynek - dwa młynki otwierające się i zamykające na zmianę - rozstrzyga prawie każdą partię."]}]},{"id":"simon","category":"games","game":"SimonGame","title":"Simon","keywords":["simon","pamięć","sekwencja","pola","pojedynek","senso"],"sections":[{"h":"Tryby gry","body":["- Klasyczny: powtórz sekwencję dokładnie. Każda runda dokłada jedno pole.","- Speed: jak klasyczny, ale odtwarzanie z rundy na rundę przyspiesza.","- Reverse: sekwencję trzeba wprowadzić od tyłu.","- Pojedynek: dwaj gracze budują sekwencję na zmianę - najpierw powtórzyć wszystko, potem dołożyć jedno pole. Kto się pomyli, przegrywa.","- Mieszany: tryb zmienia się co rundę między klasycznym, Speed i Reverse."]},{"h":"Dźwięk, pola i sterowanie","body":["Liczba pól - 4, 6 albo 9 - ustala trudność.","Dźwięk jest wyłączony (same kolory), włączony (każde pole ma swój ton) albo mieszany, gdzie jedne rundy brzmią, a inne nie. Przełącznik dźwięku w opcjach ma pierwszeństwo.","- Mysz: kliknij pole. Klawiatura: klawisze [1] do [9].","- W trakcie odtwarzania gra nie przyjmuje wejścia - poczekaj na swoją kolej.","- Po błędzie: [Enter] jeszcze raz, [S] powrót do ustawień."]},{"h":"Punkty i wskazówki","body":["Wynikiem jest najdłuższa bezbłędnie powtórzona sekwencja; pojedynek nie jest punktowany.","Wskazówka: powtarzaj kolory albo liczby w myślach. Z dźwiękiem zapamiętuje się dużo łatwiej - dlatego ustawienie mieszane jest najtrudniejsze."]}]},{"id":"billiard","category":"games","game":"BilliardGame","title":"Bilard (Billiards)","keywords":["bilard","pool","8-ball","9-ball","kij","3d"],"sections":[{"h":"Warianty","body":["- 8-ball: najpierw wbij całą swoją grupę - pełne albo połówki - a potem czarną. Grupa zostaje przydzielona przy pierwszej prawidłowo wbitej bili.","- 9-ball: zawsze najpierw uderz najniższą bilę; kto prawidłowo wbije dziewiątkę, wygrywa.","- Trening: bez zasad i bez przeciwnika - wbij tyle bil, ile zdołasz. Przy pustym stole następuje nowe rozbicie, a licznik idzie dalej."]},{"h":"Uderzenie i widoki","body":["- Mysz: prowadzi celowanie, przytrzymany lewy przycisk ładuje siłę, puszczenie uderza.","- Klawiatura: [Lewo] i [Prawo] celują, [Góra] i [Dół] regulują siłę, [Spacja] uderza.","- Po faulu biała jest w ręce: ustaw ją myszą na wolnym miejscu i kliknij.","- [V] zmienia widok: 2D z góry, 3D jako stały widok skośny albo Swobodny - tam obracasz kamerę wokół stołu przytrzymanym prawym przyciskiem myszy. Wybór jest zapisywany."]},{"h":"AI i punkty","body":["Do wyboru są trzy poziomy AI; we dwoje uderzacie na zmianę przy jednym komputerze.","Wynik liczy partie wygrane z AI, a w trybie treningu wbite bile.","Po partii: [Enter] nowa partia, [S] powrót do ustawień."]}]},{"id":"slidepuzzle","category":"games","game":"SlidingPuzzleGame","title":"Przesuwana układanka","keywords":["przesuwana układanka","piętnastka","piętnaście","kafelki","liczby","przesuwanie"],"sections":[{"h":"Jak grać","body":["Ułóż ponumerowane kafelki z powrotem w kolejności (1, 2, 3 …); luka pozostaje w prawym dolnym rogu.","Kafelki mogą przesuwać się tylko w pustą lukę. Trzy rozmiary: 3×3 (łatwy), 4×4 (klasyczny) i 5×5 (trudny).","Plansza jest tasowana wieloma losowymi ruchami, więc zawsze da się ją rozwiązać."]},{"h":"Sterowanie","body":["- Kliknij kafelek w tym samym wierszu lub kolumnie co luka, aby przesunąć całą linię.","- Strzałki wpychają kafelek sąsiadujący z luką do niej."]},{"h":"Punkty","body":["Zaczynasz z bazowym wynikiem zależnym od rozmiaru; każdy ruch i każda sekunda trochę odejmują. Szybkie rozwiązanie przy niewielu ruchach daje najlepszy wynik.","Po rozwiązaniu Enter/kliknięcie od razu rozpoczyna nową planszę."]}]},{"id":"mastermind","category":"games","game":"MastermindGame","title":"Mastermind","keywords":["mastermind","kod kolorów","kod","zgadywanie","kołki","logika"],"sections":[{"h":"Jak grać","body":["Komputer wybiera ukryty kod z kolorowych kołków (kolory mogą się powtarzać). Rozszyfruj go wiersz po wierszu.","Po każdej próbie dostajesz kołki oceny: CZARNY kołek = właściwy kolor na właściwym miejscu, BIAŁY kołek = właściwy kolor na złym miejscu. Kolejność kołków oceny nie zdradza, którego kołka dotyczy.","Tryby: Łatwy (4 kołki, 6 kolorów, 12 wierszy), Klasyczny (4/6, 10 wierszy) i Trudny (5 kołków, 8 kolorów)."]},{"h":"Sterowanie","body":["- Kliknij kolor na dole (lub klawisze 1–8), aby wypełnić następne puste miejsce.","- Kliknij umieszczony kołek, aby go usunąć; < lub Backspace usuwa ostatni.","- OK lub Enter sprawdza cały wiersz."]},{"h":"Punkty","body":["Podobnie jak w Wordle to niekończąca się seria: każdy rozszyfrowany kod daje punkty (mniej prób + trudniejszy tryb = więcej), potem od razu pojawia się nowy kod.","Pierwszy kod, którego nie zdołasz rozszyfrować, kończy grę - suma to twój najlepszy wynik."]}]},{"id":"bubbleshooter","category":"games","game":"BubbleShooterGame","title":"Bubble Shooter","keywords":["bubble shooter","puzzle bobble","bąbelki","kulki","strzelanie","grupy"],"sections":[{"h":"Jak grać","body":["Strzelaj bąbelkami w górę na pole o strukturze plastra miodu. Gdy zetkną się trzy lub więcej w tym samym kolorze, grupa pęka.","Bąbelki, które po pęknięciu grupy tracą połączenie z górnym rzędem, spadają i dają punkty bonusowe.","Tryby: Łatwy (4 kolory, brak nowych rzędów), Klasyczny (5 kolorów, od czasu do czasu dochodzi dodatkowy rząd) i Trudny (6 kolorów, szybciej)."]},{"h":"Sterowanie","body":["- Działo celuje w stronę myszy; strzałki lewo/prawo także nim obracają.","- Lewe kliknięcie lub Space strzela. Bąbelki odbijają się od bocznych ścian.","- Mały bąbelek po lewej stronie działa to twój następny kolor."]},{"h":"Punkty","body":["Pęknięte i strącone bąbelki dają punkty; oczyszczenie całego pola daje bonus.","Gdy tylko bąbelek zablokuje się poniżej czerwonej linii, gra się kończy - suma to twój najlepszy wynik."]}]},{"id":"hangman","category":"games","game":"HangmanGame","title":"Wisielec","keywords":["wisielec","słowo","zgadywanie","litery","szubienica"],"sections":[{"h":"Jak grać","body":["Odgaduj ukryte słowo litera po literze. Każda błędna litera dorysowuje kolejną część wisielca.","Po 6 błędach rysunek jest kompletny i runda jest przegrana.","Tryby według długości słowa: Krótkie słowa (3–5), Mieszane (3–12) i Długie słowa (7–12). Słowa odpowiadają wybranemu językowi i używają tylko liter A–Z."]},{"h":"Sterowanie","body":["- Wpisuj litery A–Z lub klikaj je na klawiaturze ekranowej.","- Poprawne litery pojawiają się w słowie; błędne zmieniają klawisz na szary."]},{"h":"Punkty","body":["Niekończąca się seria: każde odgadnięte słowo daje punkty (więcej pozostałych żyć i dłuższe słowa = więcej), potem od razu pojawia się nowe słowo.","Pierwsza porażka kończy grę - suma to twój najlepszy wynik."]}]},{"id":"blockjump","category":"games","game":"BlockJumpGame","title":"Block Jump","keywords":["block jump","3d","minecraft","platformówka","skok","wspinaczka","parkour","skin","steve","tekstury"],"sections":[{"h":"Jak grać","body":["Platformówka 3D w stylu Minecrafta: przeskakuj po unoszących się blokowych platformach do świecącej wieży celu. Każdy poziom to świeży parkour generowany z ziarna i staje się coraz trudniejszy.","Kamera jest domyślnie w pierwszej osobie jak w Minecrafcie; naciśnij V, aby przełączyć na kamerę podążającą.","Spadnij poniżej platform, a stracisz życie i odrodzisz się przy ostatnim punkcie kontrolnym. Przy 0 żyć (zaczynasz z 3) przejście się kończy."]},{"h":"Wygląd jak w Minecrafcie","body":["Każdy blok ma prawdziwą teksturę pikselową: trawa z zielonym nawisem, ziemia, kamień, dębowe deski, blok diamentu przy celu, bloki śluzu oraz drewno na drabiny i płoty.","Do tego postać Steve'a z animacją chodzenia w kamerze z trzeciej osoby, ręka w widoku z pierwszej osoby, promień sygnalizatora nad celem, obracające się sztabki złota zamiast monet, kwadratowe słońce, pikselowe chmury i serca na HUD.","Klawisz T zmienia poziom szczegółów tekstur: wysoki, niski lub wyłączony. Na wolniejszych komputerach 'niski' albo 'wyłączony' działa zauważalnie płynniej; wybór jest zapisywany."]},{"h":"Sterowanie","body":["- WASD lub strzałki: ruch (względem kierunku patrzenia). Space: skok. Mysz: rozglądanie się.","- Na drabinie W wspina się w górę, a S schodzi w dół. Blok sprężynowy wyrzuca cię wysoko w powietrze.","- V = widok (pierwsza/trzecia osoba), B = rozmycie ruchu, C = przechwyć/zwolnij mysz, +/- = czułość. Esc wstrzymuje i zwalnia mysz.","- T = szczegółowość tekstur (wysoka/niska/wyłączona)."]},{"h":"Rodzaje bloków","body":["- Trawa/ziemia/kamień/drewno: solidne bloki, na które skaczesz i na których stoisz.","- Drabina: wspinaj się w górę/w dół powoli. Płot: mały blok blokujący drogę - po prostu go przeskocz.","- Blok sprężynowy: wyrzuca cię wysoko (aby dosięgnąć wysokich platform). Monety unoszą się wzdłuż trasy dla dodatkowych punktów."]},{"h":"Punkty","body":["Każda moneta jest warta 50 punktów. Dotarcie do celu poziomu daje 1000 punktów plus bonus czasowy (im szybciej, tym więcej).","Punkty kumulują się na wszystkich poziomach; suma to twój najlepszy wynik."]}]},{"id":"lamatowerdefense","category":"games","game":"LamaTowerDefenseGame","title":"Tower Defense","keywords":["tower defense","wieże","fale","złoto","boss","strategia"],"sections":[{"h":"Jak grać","body":["Wrogowie maszerują falami wzdłuż ścieżki. Buduj obok wieże, aby zatrzymać ich przed wyjściem - każde przebicie kosztuje życia (bossowie 5), przy 0 koniec.","Każda mapa jest nieskończona: fale stają się coraz silniejsze, a co 8 fal nadchodzi boss. Między falami budujesz w spokoju; kolejną rozpoczynasz sam.","Zestrzelenia dają złoto, do tego bonusy za fale i 5% odsetek. Zablokowane mapy odblokujesz najlepszą falą."]},{"h":"Sterowanie","body":["- Kliknij kartę wieży (lub 1-9), potem postaw ją na polu. Prawy przycisk anuluje.","- Kliknij wieżę: Ulepsz [U] (do 3 poziomów), Sprzedaj [X] (70% zwrotu). W trybie Maksymalnym na najwyższym poziomie wybierasz specjalizację A/B.","- [Spacja] rozpoczyna falę, [F] = tempo x2, [G] = wszystkie zasięgi, kółko przewija menu budowy. Maksymalny: [Q] Meteor, [W] Nova mrozu, [E] Gorączka złota."]},{"h":"Wieże","body":["- Łucznicza = szybka i tania, Armata = obrażenia obszarowe, Mróz = spowalnia i wykrywa, Snajper = ogromny zasięg, przebija pancerz, trafia latających.","- Klasyczny dodaje Truciznę (obrażenia w czasie), Teslę (łańcuchowa błyskawica, przeciwlotnicza) i Sztandar (aura +20% obrażeń).","- Tylko Maksymalny: Moździerz (strzały łukiem przez prawie całe pole), Flak (obrona przeciwlotnicza), Laser (ciągły promień o rosnących obrażeniach) i Bank złota (dochód co falę)."]},{"h":"Wrogowie","body":["- Biegacze, sprinterzy, roje i czołgi to podstawa; później dołączają opancerzeni, regenerujący i dzielący się.","- Tylko Maksymalny: latający lecą prosto (trafiają ich tylko Snajper/Tesla/Flak/Laser), zamaskowani są widoczni tylko blisko wież mrozu, sztandaru lub snajpera, uzdrowiciele leczą sąsiadów.","- Co 8. falę maszeruje boss: mnóstwo życia, 5 żyć straty przy przebiciu, wielka nagroda."]},{"h":"Tryby i mapy","body":["- Klasyczny = główny tryb z 7 wieżami. Kompaktowy = 4 wieże, 2 poziomy, więcej złota na start - szybki początek. Maksymalny = 11 wież, gałęzie A/B, specjalni wrogowie i zdolności aktywne.","- Łąka (wolna), Kanion (od fali 5), Skrzyżowanie (od 10, ścieżka się krzyżuje - mocne dla wież, ale twardsi wrogowie) i Szpaler (od 15, budować można tylko przy ścieżce)."]},{"h":"Punkty","body":["Punkty zdobywasz za każde zestrzelenie plus bonus za falę, rosnący z numerem fali i trudnością mapy. Kamień milowy to 10 000 punktów - mniej więcej fala 18-20 na Łące."]}]},{"id":"minigolf","category":"games","game":"MiniGolfGame","title":"Minigolf","keywords":["minigolf","golf","dołek","par","hole in one","wiatrak","woda","piasek","rampa","pole","putt","tour","blokada","siła","editor","maps","ugc","tunnel","ice","magnet","booster","share","import","export"],"sections":[{"h":"Jak się gra","body":["Minigolf na 360 dołkach: 18 zbudowanych ręcznie i 342 wygenerowane. Pola Classic i Pro wprowadzają po dziewięć zbudowanych dołków, Tour oferuje 38 pól po dziewięć generowanych dołków o rosnącej trudności, a Random losuje dziewięć dołków z całości i odbija je lustrzanie.","Dołki Tour powstają z ziarna: pole 7, dołek 3 wygląda tak samo przy każdym starcie - nic nie trzeba zapisywać. Strzałki obok numeru przewijają 38 pól, a obok widnieje łączny par.","Celem jest wbicie piłki w jak najmniejszej liczbie uderzeń. Domyślnie po ośmiu uderzeniach dołek zostaje podniesiony i liczy się na minimum - kto woli grać aż do wbicia, wyłącza podnoszenie w ustawieniach (albo klawiszem [P]).","Tak samo można wyłączyć auto-celowanie: normalnie kij przed każdym uderzeniem sam wskazuje dołek - bez niego celujesz na każdym dołku samodzielnie.","We dwoje każdy gra ten sam dołek po kolei; karta wyników po prawej pokazuje par i oba rezultaty.","Na koniec rundy przycisk Dalej prowadzi wprost do kolejnego kursu (Classic -> Pro -> Tour 1 -> Tour 2 ...), więc ten sam zestaw dziewięciu dołków nigdy się nie powtarza. Jeszcze raz gra ten sam kurs, Ustawienia wracają do wyboru."]},{"h":"Sterowanie","body":["- Ruch myszy celuje. Przytrzymanie lewego przycisku ładuje siłę, puszczenie uderza.","- Przytrzymanie prawego przycisku myszy blokuje siłę: pasek staje w miejscu, złocieje i pokazuje procenty - z naładowanym uderzeniem czekasz na przerwę w wiatraku. Puszczenie ładuje dalej; zablokowana siła przetrwa nawet uderzenie, więc kolejne lewe kliknięcie uderza dokładnie tą wartością.","- Strzałki lewo/prawo celują, góra/dół ustawiają siłę, [Spacja] uderza.","- [G] włącza i wyłącza linię celowania - można ją też wyłączyć na stałe w ustawieniach.","- [Z] przełącza auto-celowanie: włączone (domyślnie) kij przed każdym uderzeniem sam obraca się w stronę dołka, wyłączone zostawia ostatnio wybrany kierunek - wtedy celujesz całkiem sam. Na tee nowego dołka kij wskazuje neutralnie w górę.","- [R] anuluje naładowane uderzenie: przycisk myszy może pozostać wciśnięty, piłka zostaje na miejscu, a uderzenie się nie liczy - po puszczeniu ładujesz od nowa. [P] przełącza podnoszenie.","- [F] resetuje bieżący dołek: uderzenia z powrotem na 0, piłka na tee - ten sam dołek, ten sam kurs. Rozegrane dołki zostają na karcie wyników."]},{"h":"Przeszkody","body":["- Piasek mocno hamuje, rampy przyspieszają zgodnie ze strzałkami.","- Woda kosztuje uderzenie karne; piłka wraca na ostatnie bezpieczne miejsce.","- Gumowe odbijacze oddają prędkość; wiatraki i ruchome bloki wymagają wyczucia czasu. Blokada siły na prawym przycisku trzyma uderzenie naładowane, aż przerwa będzie w sam raz.","- Rura: piłka znika w jednym wylocie i wychodzi drugim - kierunek i prędkość zostają zachowane.","- Lód pozwala piłce toczyć się niemal bez końca, lepkie pole zatrzymuje ją od razu.","- Przyspieszacze dają stałego kopniaka przy przejeździe, magnesy przyciągają lub odpychają.","- Bramka jednokierunkowa przepuszcza tylko zgodnie ze strzałką; z drugiej strony to ściana.","- Obrotnica porywa piłkę i wynosi ją na zewnątrz, skocznia posyła ją ponad przeszkodami.","Te osiem przeszkód dochodzi do klasycznych i można je dowolnie stawiać w edytorze dołków - patrz strona \"Własne dołki\"."]},{"h":"Punkty","body":["Każdy dołek daje 600 punktów plus 300 za każde uderzenie poniżej par (i 300 mniej za każde powyżej, nigdy poniżej 100).","Hole in one dokłada 500 punktów. Suma wszystkich dołków to rekord; dodatkowo zapisywana jest najmniejsza liczba uderzeń na każdym polu."]}]},{"id":"minigolf-maps","category":"games","title":"Własne dołki (Minigolf)","keywords":["wlasne dolki","edytor","maps","ugc","budowanie","udostepnianie","import","eksport","szablon","minigolf"],"sections":[{"h":"Budowanie dołka","body":["Na ekranie przygotowania minigolfa zakładka MAPS prowadzi do własnej kolekcji. \"Nowy\" otwiera edytor, \"Edytuj\" wraca do istniejącego dołka.","Każdy dołek potrzebuje nazwy i id. Id jest kluczem: małe litery, bez spacji, tylko a-z, 0-9, - i _. Jest też proponowaną nazwą pliku przy udostępnianiu.","Po lewej leży dołek, po prawej paleta z czterema narzędziami i piętnastoma typami przeszkód. Prostokąty się rozciąga, okrągłe rzeczy stawia jedno kliknięcie, rura wymaga dwóch - najpierw wejście, potem wyjście.","Narzędziem zaznaczania klik wybiera obiekt, przeciąganie go przesuwa, [Del] usuwa. Na dole pojawiają się wtedy wartości wybranego obiektu: szerokość, wysokość, promień, kierunek, prędkość i tak dalej.","U góry ustawiasz par oraz szerokość i wysokość dołka - od 60x80 do 160x240 jednostek. To, co przy zmniejszaniu wystawałoby, wsuwa się automatycznie do środka.","[G] przełącza przyciąganie do siatki, [U] cofa, [Y] ponawia, [S] zapisuje, a [Enter] od razu wypróbowuje dołek. [Esc] wraca - przy niezapisanych zmianach dopiero po potwierdzeniu."]},{"h":"Szablony","body":["\"Szablon\" zastępuje bieżący dołek jednym z dwunastu gotowych: Pusty, Rura, Wyspa, Wiatrak, Zygzak, Woda, Odbijaki, Rampa, Lód, Labirynt, Magnes i Skok.","Każdy szablon zawsze zostawia obok swojej sztuczki normalną drogę - dołek do przejścia wyłącznie sztuczką byłby pułapką, a nie szablonem. Wszystkie dwanaście są dowiedzione jako grywalne w par.","Szablon to punkt wyjścia, a nie wynik: dostaw własne przeszkody, przesuń start i dołek, zmień rozmiar."]},{"h":"Granie","body":["W zakładce MAPS \"Graj\" uruchamia dokładnie wybrany dołek - z własnym rekordem dla każdego dołka.","W zakładce GRA jest piąty wybór trasy, \"Własne\": wtedy cała kolekcja leci po kolei jako runda, najwyżej dziewięć dołków.","Wszystko zapisuje się w ugc.json obok gry (obok .exe w wersji skompilowanej) - w tym samym miejscu co mem.json i replay.json."]},{"h":"Udostępnianie i import","body":["\"Udostępnij\" pyta najpierw o twoją nazwę jako twórcy, a potem o nazwę pliku; ta jest już wypełniona id dołka.","\"Eksportuj jako\" otwiera zwykłe okno zapisu, \"Do Pobranych\" odkłada plik prosto w folderze Pobrane i podaje ścieżkę. Za każdym razem eksportowany jest dokładnie jeden dołek.","Plik ma rozszerzenie .lamapgzmap i zawiera JSON - możesz go wysłać jak każdy inny plik. \"Importuj\" wczytuje go z powrotem; przy imporcie przyjmowane są też pliki .json.","Jeśli id jest już zajęte, import automatycznie dokleja -2, -3 i tak dalej, zamiast nadpisać istniejący dołek.","Nazwa dołka, id i nazwa twórcy przechodzą przez filtr słów przy zapisie, eksporcie ORAZ imporcie, a sprawdza on wszystkie 14 języków. Obraźliwe treści są odrzucane - niezależnie od ustawionego języka."]}]},{"id":"pinball","category":"games","game":"PinballGame","title":"Pinball","keywords":["pinball","fliper","multiball","bumper","tilt","stół","jackpot","cel","łapacz","potrącenie"],"sections":[{"h":"Jak się gra","body":["Automat do flipera z trzema stołami: Classic z trzema bumperami i jedną serią celów, Space z czterema bumperami w romb i dwiema seriami, Lama z otwartym polem i sześcioma celami w łuku.","Każda gra daje 3 lub 5 kul. Po wystrzale przez sześć sekund działa ratunek kuli: jeśli kula zginie w tym czasie, wraca do wyrzutni.","We dwoje gracze zmieniają się kula po kuli; wyniki stoją jeden pod drugim w kolumnie informacyjnej."]},{"h":"Sterowanie","body":["- Przytrzymaj klawisz akcji (domyślnie [Spacja]), aby napiąć wyrzutnię, i puść, aby wystrzelić. Za słabo? Kula wraca i można spróbować jeszcze raz.","- Lewo/prawo (a także lewy/prawy [Shift]) obsługują flipery. Myszą: lewa połowa ekranu = lewy fliper.","- Klawisz w górę potrąca stół. Trzy potrącenia zbyt szybko po sobie dają TILT - flipery są martwe aż do straty kuli."]},{"h":"Punkty i multiball","body":["Bumpery dają 100, slingshoty 50, a cele 250 - wszystko razy aktualny mnożnik (do x5).","Zbicie pełnej serii celów albo zebranie wszystkich czterech torów L-A-M-A podnosi mnożnik o jeden.","Trzy kule zamknięte w łapaczu uruchamiają multiball: trzy kule naraz, a bumpery płacą jackpot 2500 punktów."]},{"h":"Wskazówki","body":["Kolumna po prawej pokazuje mnożnik, zamknięte kule, zbite serie i pozostały czas ratunku kuli.","Potrącenie ratuje kulę tuż przed stratą - ale oszczędnie: licznik zeruje się dopiero po czterech spokojnych sekundach.","Rekord zapisywany jest osobno dla każdego stołu, a wynik partii liczy się jako najlepszy wynik."]}]},{"id":"bowling","category":"games","game":"BowlingGame","title":"Bowling","keywords":["bowling","strike","spare","kręgle","frame","rotacja","hook","tor","rynna","pocket"],"sections":[{"h":"Jak się gra","body":["Dziesięć frame'ów według oficjalnych zasad: dwa rzuty na frame, strike i spare dają punkty bonusowe, a dziesiąty frame daje rzuty dodatkowe. Maksimum to 300.","Karta wyników tuż pod nagłówkiem pokazuje wszystkie dziesięć frame'ów z rzutami (X, /, -) i sumą bieżącą.","We dwoje gracze zmieniają się frame po frame."]},{"h":"Rzut w czterech krokach","body":["1. Pozycja na linii, 2. kąt celowania, 3. rotacja (w lewo lub w prawo), 4. siła.","Każdy suwak waha się sam; klawisz akcji albo kliknięcie go zatrzymuje.","Lewo/prawo pozwalają ustawić suwak ręcznie - wahanie wtedy ustaje."]},{"h":"Rotacja i olej","body":["Tor jest z przodu naoliwiony: rotacja łapie dopiero w ostatniej trzeciej części i ciągnie kulę do pocketu między kręglami 1 i 3.","Zejście z toru w bok kończy się w rynnie - taki rzut liczy zero.","Na poziomie Pro suwaki wahają się szybciej, a tor rozrzuca nieco mocniej; na Łatwym wszystko jest spokojniejsze. [G] przełącza linię pomocy."]},{"h":"Kręgle i punkty","body":["Dziesięć kręgli to koła z prawdziwą masą: kula je uderza, a one przewracają się nawzajem. Strike jest więc wynikiem fizyki, a nie przypadku.","Suma gry to rekord; dodatkowo zapisywany jest najlepszy wynik dla każdego poziomu."]}]},{"id":"crossyroad","category":"games","game":"CrossyRoadGame","title":"Crossy Road","keywords":["kura","ulica","rzeka","tory","pociąg","orzeł","monety","postacie","dzienna","voxel"],"sections":[{"h":"Sterowanie","body":["Skacz pole po polu strzałkami lub [W] [A] [S] [D]. [Spacja], [Enter] albo kliknięcie myszą skaczą do przodu.","- Jeśli wciśniesz kolejny kierunek jeszcze w locie, skoczysz od razu po wylądowaniu. Przytrzymanie klawisza nie skacze bez końca.","Po game over: [Enter] = jeszcze raz, [F] = postacie, [S] = ustawienia."]},{"h":"Trawa, ulice, rzeki i tory","body":["Trasa powstaje bez końca rząd po rzędzie - zawsze istnieje przejście.","- Trawa: bezpieczna, ale drzewa i kamienie zagradzają drogę.","- Ulice: samochody i ciężarówki cię rozjadą. Im dalej zajdziesz, tym szybszy i gęstszy ruch.","- Rzeki: stać możesz tylko na kłodach i liściach lilii. Kłody niosą cię ze sobą - kto wypłynie poza krawędź ekranu, odpada.","- Tory: gdy miga czerwone światło i dzwoni dzwonek, mniej więcej sekundę później nadjeżdża pociąg. Dalej czekają całe stacje z nawet 5 torami pod rząd."]},{"h":"Orzeł i punkty","body":["Kamera powoli przesuwa się naprzód. Kto marudzi zbyt długo albo cofnie się o więcej niż trzy rzędy, tego porywa orzeł - wcześniej ostrzega czerwony pasek na dole ekranu.","Punkty = najdalszy osiągnięty rząd. W trybie Bez końca to twój rekord (kamień milowy: 150 rzędów).","Od rzędu 50 zmieniają się dzień i noc: w nocy świecą reflektory, pociągi i monety."]},{"h":"Monety i postacie","body":["Na trasie leżą monety, wielka moneta jest warta 5. Zebrane monety zostają zapisane.","W zakładce POSTACIE kupujesz za nie nowe postacie: żabę, świnkę, pingwina, kota, lisa, lamę, robota, ducha i jednorożca (od 25 do 250 monet). Kurę masz od początku.","- Osiągnięcia: „Nowy wygląd” za pierwszą kupioną postać, „Torowy akrobata” za 5 torów pod rząd."]},{"h":"Tryby i opcje","body":["- Bez końca: w każdej rundzie nowa trasa, liczy się do rekordu.","- Trasa dnia: dziś taka sama dla wszystkich (także w wersji przeglądarkowej), z własnym rekordem dnia - nie liczy się do rekordu.","W ustawieniach włączasz i wyłączasz cienie [H] oraz zmianę dnia i nocy [N]; Lewo/Prawo przełącza między twoimi postaciami."]}]},{"id":"geodash","category":"games","game":"GeometryDashGame","title":"Geometry Dash","keywords":["geometry dash","rytm","kostka","statek","kula","ufo","fala","portal","wyrzutnia","monety","gwiazdki","trening","checkpoint","demon","muzyka","poziom"],"sections":[{"h":"Jak grać","body":["Twoja postać sama pędzi w prawo - ty decydujesz tylko, kiedy skoczyć albo lecieć. Kolec, dół albo czołowe zderzenie z blokiem: wybuch, a chwilę później rusza już kolejna próba.","Poziom jest ukończony, gdy dotrzesz do mety. Pasek u góry pokazuje postęp w procentach, w prawym górnym rogu widać monety z tej próby, a na starcie w poziomie unosi się licznik prób.","Każdy poziom ma własną ścieżkę dźwiękową; tło, podłoże i kule pulsują w rytm muzyki. Muzykę, pasek postępu i automatyczne punkty kontrolne włączasz na ekranie wyboru poziomu, pod kartą poziomu."]},{"h":"Sterowanie","body":["- [Spacja], [Góra], [W], [Enter] lub lewy przycisk myszy: skok albo lot. Przytrzymanie działa jak ciągłe wciskanie - kostka odbija się wtedy od razu po każdym lądowaniu.","- [R] od razu zaczyna od nowa, [Q] lub [Backspace] wraca do wyboru poziomu, [Esc] pauzuje.","- [P] włącza i wyłącza tryb treningowy; w nim [Z] stawia punkt kontrolny, a [X] usuwa ostatni.","- Wybór poziomu: [Lewo]/[Prawo] przełączają poziomy, [1] do [8] przechodzą prosto do poziomu, [Enter] startuje, [P] wybiera Normalny lub Trening, [M] przełącza muzykę, [Tab] przechodzi do zakładki POZIOMY.","Każde wciśnięcie dostaje znacznik czasu i działa dokładnie w tym kroku fizyki (1/240 sekundy), w którym nastąpiło - skok wychodzi więc idealnie, nawet gdy komputer na chwilę przytnie."]},{"h":"Pięć form","body":["Portale zmieniają twoją postać - każda forma lata inaczej:","- Kostka: wciśnięcie = skok. Ląduje na blokach; uderzenie w ich bok kończy próbę.","- Statek: przytrzymanie = wznoszenie, puszczenie = opadanie.","- Kula: stuknięcie na ziemi odwraca grawitację - potem toczy się dalej po suficie.","- UFO: każde stuknięcie to małe machnięcie skrzydłami, także w powietrzu.","- Fala: przytrzymanie = ukośnie w górę, puszczenie = ukośnie w dół. Jest malutka, ale każde dotknięcie bloku ją roztrzaskuje.","Statek, kula, UFO i fala latają w korytarzu między podłożem a sufitem - jego wysokość wyznacza portal."]},{"h":"Wyrzutnie, kule i portale","body":["- Wyrzutnie leżą na ziemi i działają przy dotknięciu: żółta = wysoki skok, różowa = mały skok, niebieska = odwrócenie grawitacji.","- Kule unoszą się w powietrzu i działają tylko wtedy, gdy wciśniesz przycisk, dotykając ich - w tych samych kolorach. Krótki bufor wybacza odrobinę za wczesne wciśnięcie.","- Portale grawitacji: żółty odwraca świat do góry nogami, niebieski przywraca go. Portale prędkości przełączają na 0,5x, 1x, 2x lub 3x.","- Do tego dochodzą półbloki, małe kolce, doły bez podłoża i wyzwalacze koloru, które zmieniają barwę tła i podłoża."]},{"h":"8 poziomów","body":["- Lama Launch (Łatwy, 1 gwiazdka) i Neon Steps (Łatwy, 2 gwiazdki): skoki, wyrzutnie, kule i pierwszy statek.","- Orbit Garden (Normalny, 3 gwiazdki): łańcuchy kul, do góry nogami pod sufitem, statek z podwójną prędkością.","- Gravity Tide (Trudny, 4 gwiazdki) i Skyline Rush (Trudny, 5 gwiazdek): portale grawitacji, kula, UFO, doły i potrójna prędkość.","- Crystal Caves (Trudniejszy, 7 gwiazdek) i Wave Reactor (Szalony, 9 gwiazdek): wszystkie pięć form, wąskie bramy i tunele fali.","- Lama Inferno (Demon, 10 gwiazdek): potrójna prędkość i wszystko naraz.","Udowodniono, że każdy poziom da się przejść razem ze wszystkimi trzema monetami: przy budowie solver ukończył go prawdziwym kodem gry - a jego rozwiązanie działa nawet przesunięte o 1/240 sekundy."]},{"h":"Tryb treningowy","body":["W trybie treningowym po rozbiciu grasz dalej od ostatniego punktu kontrolnego zamiast od startu - zielone romby zaznaczają je w poziomie, a muzyka po prostu gra dalej.","Automatyczne punkty kontrolne powstają mniej więcej co dwie sekundy (można je wyłączyć), [Z] stawia własne, a [X] usuwa ostatni.","Trening ma własny rekord i nie daje ani gwiazdek, ani monet."]},{"h":"Gwiazdki, monety i osiągnięcia","body":["Kto ukończy poziom w trybie normalnym, dostaje jego gwiazdki. W każdym poziomie ukryte są też trzy sekretne monety, często z dala od najłatwiejszej drogi. Liczą się, gdy ukończysz z nimi poziom - a każda jest warta kolejną gwiazdkę.","Twój rekord to suma gwiazdek (najwyżej 65) i może tylko rosnąć. Dla każdego poziomu gra zapamiętuje najlepszy wynik procentowy w trybie Normalnym i Treningu, znalezione monety oraz liczbę prób.","- Osiągnięcia: \"W rytmie\" za pierwszy ukończony poziom, \"Łowca monet\" za wszystkie trzy monety z poziomu, \"Pogromca demonów\" za Lama Inferno - oraz kamień milowy przy 20 gwiazdkach.","W zakładce POZIOMY budujesz, grasz i udostępniasz własne poziomy - zobacz stronę \"Własne poziomy (Geometry Dash)\"."]}]},{"id":"geodash-levels","category":"games","title":"Własne poziomy (Geometry Dash)","keywords":["własne poziomy","edytor","poziomy","ugc","budowanie","udostępnianie","import","eksport","zweryfikowany","lamapgzlevel","geometry dash"],"sections":[{"h":"Budowanie poziomu","body":["Zakładka POZIOMY w wyborze poziomów Geometry Dash to twoja własna kolekcja (do 60 poziomów). \"Nowy\" otwiera edytor poziomów, \"Edytuj\" wraca do istniejącego poziomu.","Po lewej jest płótno z siatką, po prawej paleta: u góry Zaznacz i Gumka, pod nimi sześć grup - Bloki, Pułapki, Wyrzutnie i kule, Portale, Prędkość i Dodatki (sekretne monety, wyzwalacz koloru). [1] do [6] wybierają grupy bezpośrednio.","- Kliknięcie lub przeciąganie stawia wybrany obiekt, [R] go obraca: kolce i półbloki w czterech kierunkach, wyrzutnie w górę lub w dół.","- Z narzędziem Zaznacz przeciąganie przesuwa obiekt, a [Del] go usuwa. Prawy przycisk zawsze kasuje; przeciąganie prawym przyciskiem, kółko myszy, strzałki lub [A]/[D] przewijają.","- Na dole widać wartości wybranego obiektu: wysokość korytarza przy portalach formy, a przy wyzwalaczu koloru cel (tło lub podłoże), kolor i czas przejścia.","- Pasek na samym dole pokazuje cały poziom w skrócie - kliknięcie przenosi w to miejsce.","[U] cofa, [Y] ponawia, [G] pokazuje lub ukrywa siatkę, [S] zapisuje. [Esc] wraca - przy niezapisanych zmianach dopiero po potwierdzeniu.","Najwyżej trzy monety na poziom. Meta ustawia się automatycznie kawałek za ostatnim obiektem."]},{"h":"Ustawienia poziomu","body":["Zębatka otwiera ustawienia poziomu: prędkość startową (od 0,5x do 3x), formę startową, styl muzyki (Energiczny, Chiptune, Marzycielski, Mroczny lub bez muzyki), tempo w BPM oraz kolor tła i podłoża.","Nazwa i id są w pasku na górze. Id to klucz: małe litery, bez spacji, tylko a-z, 0-9, - i _ - a zarazem proponowana nazwa pliku przy udostępnianiu."]},{"h":"Testowanie i weryfikacja","body":["\"Test\" ([Enter]) uruchamia poziom od startu, \"Stąd\" ([T]) od bieżącego miejsca - portale przed nim liczą się wtedy jako przebyte. [Esc] wraca do płótna.","Jeśli ukończysz swój poziom w teście od samego startu i bez trybu treningowego, dostaje zielony znaczek \"zweryfikowany\". Każda późniejsza zmiana obiektów, prędkości lub formy startowej go usuwa - zmiana kolorów, nazwy i muzyki nie.","W zakładce POZIOMY \"Graj\" uruchamia wybrany poziom normalnie, z własnym rekordem i licznikiem prób."]},{"h":"Udostępnianie i import","body":["\"Udostępnij\" pyta o twoją nazwę jako twórcy i o nazwę pliku. \"Eksportuj jako\" otwiera okno zapisu, \"Do Pobranych\" zapisuje plik od razu w folderze Pobrane.","Plik ma rozszerzenie .lamapgzlevel i zawiera JSON. \"Importuj\" wczytuje go z powrotem (także .json); jeśli id jest już zajęte, automatycznie dopisywane jest -2, -3 ... Znaczek weryfikacji wędruje razem z poziomem.","Nazwa, id i twórca przechodzą przez filtr słów wszystkich 14 języków przy zapisie, eksporcie ORAZ imporcie.","Wszystko zapisuje się w ugc.json obok gry - w tym samym pliku co własne dołki do minigolfa. W wersji przeglądarkowej poziomy zostają w pamięci przeglądarki, a udostępnianie pobiera plik."]}]},{"id":"battleship","category":"games","game":"BattleshipGame","title":"Battleship","keywords":["battleship","statki","flota","salwa","radar","ai","rozstawianie","zatapianie"],"sections":[{"h":"Jak grać","body":["Dwie floty, każda na własnym morzu 10x10: lotniskowiec (5 pól), pancernik (4), krążownik (3), okręt podwodny (3) i niszczyciel (2). Gracze na zmianę strzelają w pole na planszy przeciwnika.","Po lewej jest duża plansza celu z radarem, po prawej twoje wody i przegląd obu flot. Biały pierścień oznacza pudło, płomienie - trafienie. Gdy wszystkie pola statku zostaną trafione, statek tonie, a jego zarys zostaje odsłonięty.","Wygrywa ten, kto pierwszy zatopi wszystkie pięć wrogich statków. Podsumowanie pokazuje potem strzały, trafienia, celność, tury i pozostałe statki obu stron."]},{"h":"Rozstawianie floty","body":["- Przeciągnij statki myszą z doku po prawej na planszę - albo kliknij statek, przesuń go i kliknij ponownie. Ustawione statki przesuwa się tak samo.","- [R] lub prawy przycisk myszy obraca trzymany statek (albo statek pod kursorem).","- Podgląd świeci na zielono, gdy pozycja jest dozwolona, a na czerwono, gdy nie jest.","- Klawiatura: strzałki przesuwają ramkę, [Space] podnosi i odkłada statek, [Enter] bierze następny brakujący statek.","- [X] rozstawia losowo, [C] usuwa wszystkie statki. Z pełną flotą [Enter] lub \"Gotowe!\" rozpoczyna bitwę.","Ostatnie ustawienie zostanie ponownie zaproponowane w kolejnej rundzie."]},{"h":"Zasady w ustawieniach","body":["Wszystkie trzy przełączniki zapisują się od razu i obowiązują obie strony:","- Statki mogą się stykać: WYŁ. wymaga co najmniej jednego wolnego pola wokół każdego statku, także po skosie. Strefa zakazana jest podświetlona podczas rozstawiania.","- Salwa: w każdej turze masz tyle strzałów, ile twoich statków jeszcze pływa - kto traci statki, strzela mniej.","- Kolejny strzał po trafieniu: każde trafienie oddaje strzał, więc strzelasz dalej, dopóki trafiasz."]},{"h":"Sterowanie","body":["- Mysz: kliknij pole na planszy celu.","- Klawiatura: strzałki lub twoje klawisze ruchu celują, [Space] lub [Enter] strzela.","- Po rundzie: [Enter] = nowa runda, [S] = powrót do ustawień. [Esc] pauzuje."]},{"h":"Poziomy AI","body":["- Łatwy strzela losowo i tylko czasem kontynuuje po trafieniu.","- Średni szuka losowo, po trafieniu sprawdza sąsiednie pola i wydłuża linie trafień aż do końca statku.","- Trudny liczy dla każdego pola, w ilu wciąż możliwych położeniach pozostałe statki mogłyby je zajmować (z uwzględnieniem zasady stykania), i strzela w najbardziej prawdopodobne. Podczas szukania używa wzoru szachownicy dopasowanego do najmniejszego pozostałego statku.","Średnio AI potrzebuje około 70 (Łatwy), 60 (Średni) i 45 strzałów (Trudny), by zatopić całą flotę - i wie tylko to, co ty też widzisz."]},{"h":"2 graczy","body":["W trybie dla wielu graczy gracie na zmianę przy jednym komputerze. Przed rozstawianiem i przed każdą turą ekran przekazania zakrywa obie floty, aż następny gracz potwierdzi klawiszem [Enter] lub kliknięciem.","Pokazuje też, ile strzałów i trafień miał ostatni atak na twoją flotę. Wersja przeglądarkowa gra tylko przeciw AI."]},{"h":"Punkty i osiągnięcia","body":["Każde zwycięstwo z AI to jeden punkt; rekord to najwięcej zwycięstw w jednej sesji. Tryb dla 2 graczy nie jest liczony.","- Nietknięta flota: pokonaj AI, nie tracąc ani jednego statku.","- Wielki admirał: zatop flotę trudnego AI."]},{"h":"Wskazówki","body":["- Rozłóż statki po całej planszy i nie ustawiaj wszystkich przy krawędzi.","- Przy szukaniu wystarczy co drugie pole (szachownica) - gdy zostały już tylko długie statki, nawet co trzecie.","- Bez zasady stykania każde pole wokół zatopionego statku to na pewno woda."]}]},{"id":"casino","category":"games","game":"CasinoGame","title":"Casino","keywords":["kasyno","casino","ruletka","automat","lama","jackpot","obroty gratis","żetony","zakłady"],"sections":[{"h":"Bank Lamy","body":["Casino, Blackjack i Poker korzystają z tego samego konta: żetonów Lamy (start 1000). Stawki są pobierane od razu, wygrane dopisywane - wszystko jest trwale zapisywane.","Każda gra prowadzi własny bilans. Rekord Casino to najwyższy stan 1000 + bilans Casino; wygrane w Blackjacku czy Pokerze się tu nie liczą.","Przy bankructwie (mniej niż minimalna stawka) dostajesz kredyt z banku: konto wraca do 1000. Kredyty nie liczą się do żadnego bilansu; ich liczba jest widoczna w prawym górnym rogu."]},{"h":"Ruletka - obstawianie","body":["Europejskie koło z 37 polami (0 do 36). Wartość żetonu wybierasz na dole: 1, 5, 25, 100 lub 500 (klawisze [1] do [5] lub kółko myszy).","Lewy klik stawia żeton, prawy klik go zdejmuje. Miejsce kliknięcia decyduje o zakładzie:","- Środek liczby: pojedyncza, płaci 35:1","- Krawędź między dwiema liczbami: podwójna, 17:1","- Zewnętrzna linia kolumny liczb: trójka, 11:1 (przy zerze także 0-1-2 i 0-2-3)","- Róg między czterema liczbami: czwórka, 8:1 (na zewnątrz przy zerze: 0-1-2-3)","- Róg na zewnętrznej linii między dwiema kolumnami: szóstka, 5:1","- Kolumna (2:1) i tuzin (2:1), czerwone/czarne, parzyste/nieparzyste oraz małe 1-18 / duże 19-36 (każdy 1:1)","Obok koła widać, jaki zakład jest pod myszą i ile płaci."]},{"h":"Ruletka - kręcenie","body":["[Enter] lub ZAKRĘĆ rozpoczyna rundę: stawka zostaje pobrana, a zwycięska liczba wylosowana. Kulka zjeżdża spiralą i wpada dokładnie w to pole - [Spacja] lub kliknięcie przyspiesza.","Powtórz [R] stawia zakłady z ostatniej rundy, Podwój [D] podwaja wszystkie zakłady, Wyczyść [Backspace] opróżnia stół.","U góry widać 12 ostatnich liczb; wygrane zakłady pokazują swoją wypłatę."]},{"h":"Automat Lamy","body":["5 bębnów, 3 rzędy, 10 linii wygrywających. Linie płacą od 3 jednakowych symboli od lewej do prawej; numery po bokach pokazują przebieg każdej linii (najechanie myszą = pokaż linię).","Stawka na linię: 1, 2, 5 lub 10 ([+]/[-] lub kółko myszy) - zawsze grasz na wszystkich 10 liniach.","- Lama = wild: zastępuje każdy symbol oprócz złotej monety. 5 lam na jednej linii to Jackpot Lamy.","- Złota moneta = scatter: 3, 4 lub 5 monet w dowolnym miejscu płaci 2, 10 lub 50 razy stawkę łączną i daje 10 obrotów gratis, w których wszystkie wygrane liczą się podwójnie. Obroty gratis można aktywować ponownie.","Tabela wygranych pokazuje wszystkie wypłaty dla aktualnej stawki. Zwrot dla gracza wynosi 96,1% - obliczony dokładnie z taśm bębnów."]},{"h":"Automat Lamy - sterowanie","body":["[Spacja], [Enter] lub kliknięcie w bębny kręci; ponowne naciśnięcie w trakcie przyspiesza.","Autospin: [A] uruchamia 10 rund, [Shift]+[A] 25 rund (albo przycisk Auto), ponowne naciśnięcie zatrzymuje. [T] włącza turbo, [I] otwiera tabelę wygranych.","Wygrane obroty gratis są od razu zapisywane i będą kontynuowane przy następnej grze."]},{"h":"Osiągnięcia","body":["- Kamień milowy Casino: rekord 5000","- W dziesiątkę: wygraj zakładem na pojedynczą liczbę w ruletce","- Jackpot Lamy: 5 lam na jednej linii wygrywającej"]}]}]};
